window.MG_LAZY_DATA["data/lazy/courses/b102-5e250f114ce405b1.json"]={sha256:"5e250f114ce405b15f90fc31c041debc8e9cb55e15cf35974ba840a391610390",value:{"id":"b102","category":"underground","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v6-channel-infrastructure","v6-channel-tbm","v6-channel-construction","v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"stages":[{"id":"b102-stage01","order":1,"steps":[{"id":"b102-v6-01","sequence":1,"order":1,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":[],"title":"建立地層與路線剖面","titleEn":"Build a ground–alignment section","objective":"分開已觀測地層與推估延伸。","objectiveEn":"Separate observed strata from inferred continuity.","instruction":"自繪兩岸及海床，將白堊泥灰岩畫成有厚度的帶狀層。以實線代表假設鑽孔位置、虛線表示孔間推論，另標出可能含水或破碎區。","instructionEn":"Sketch both coasts and seabed with a chalk-marl band. Mark hypothetical boreholes with solid symbols and inferred continuity with dashed lines; add potentially wet or fractured zones.","observation":"觀察最短直線是否始終位於選定地層內。","observationEn":"Check whether the shortest straight alignment stays inside the selected layer.","failure":"把「主要穿越某地層」誤解成全線均質且不會滲水。","failureEn":"Treating a dominant stratum as proof of uniform, watertight conditions everywhere.","check":"剖面須有觀測／推論圖例及兩處需補充調查的位置。","checkEn":"Include an observation/inference key and two locations needing further investigation.","knowledge":[{"id":"b102-v6-01-k1","title":"地層追蹤","titleEn":"Stratum following","text":"路線可以為了維持較合適地層而調整，不必是兩點最短連線。","textEn":"Alignment may follow favorable ground rather than the shortest line between two points."},{"id":"b102-v6-01-k2","title":"局部差異","titleEn":"Local variation","text":"斷層、褶皺和含水差異會使同名岩層的施工表現不同。","textEn":"Faults, folding and water conditions can change behavior within a named rock layer."}],"quiz":{"options":["標成推論並列出驗證需求","延用最近鑽孔結果當成全段實測","從剖面刪掉不確定區"],"optionsEn":["As an inference with a verification need","Treat the nearest borehole as measurement of the whole interval","Remove the uncertain area from the section"],"answer":0,"question":"鑽孔間出現未確認的構造，應如何標記？","questionEn":"How should an unconfirmed feature between boreholes be shown?","explanation":"地質模型應保留不確定性，讓後續觀察能修正它。","explanationEn":"A geological model should preserve uncertainty so subsequent observations can revise it."}},{"id":"b102-v6-02","sequence":2,"order":2,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-01"],"title":"連結兩岸測量基準","titleEn":"Connect survey references on both shores","objective":"理解長距離對向掘進的基準一致性。","objectiveEn":"Understand reference consistency in long opposing drives.","instruction":"畫出地面控制網、井下傳遞點與隧道導線的關係。用自設兩岸座標示例，先核對單位、方向與高程基準，再比較預期會合位置。","instructionEn":"Diagram surface controls, underground transfer points and tunnel traverses. With invented coordinates from both shores, reconcile units, orientation and height datum before comparing predicted meeting positions.","observation":"比較共同偏移和兩側相向軸線不一致造成的不同結果。","observationEn":"Compare a common offset with disagreement between opposing drive axes.","failure":"未統一高程基準，就把兩側標高差當成施工誤差。","failureEn":"Treating height differences as construction error before reconciling datums.","check":"交付一張基準對照表及一個可重現的示例閉合檢查。","checkEn":"Submit a reference table and a reproducible example closure check.","knowledge":[{"id":"b102-v6-02-k1","title":"基準傳遞","titleEn":"Reference transfer","text":"地面控制需經過可追溯的傳遞才能用於地下方向判讀。","textEn":"Surface control must be transferred traceably before underground directions can be interpreted."},{"id":"b102-v6-02-k2","title":"誤差累積","titleEn":"Error accumulation","text":"長距離測量的小方向誤差可能累積成明顯位置差。","textEn":"Small directional errors over long distances can accumulate into substantial positional differences."}],"quiz":{"options":["立即修改襯砌環直徑","單位、基準面及控制點版本","只採用數字較小的一組"],"optionsEn":["Immediately change lining-ring diameter","Units, datum and control-point versions","Use whichever numbers are smaller"],"answer":1,"question":"兩隊高程數字不一致時，第一項核對是什麼？","questionEn":"Two teams report different elevations. What should be checked first?","explanation":"先確定數據在同一參考系，才能判斷幾何偏差。","explanationEn":"Data must share a reference system before geometric discrepancies are assessed."}},{"id":"b102-v6-03","sequence":3,"order":3,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-02"],"title":"選擇開挖配置的證據","titleEn":"Identify evidence for excavation configuration","objective":"把機台功能與地層及地下水問題配對。","objectiveEn":"Match machine functions to ground and groundwater questions.","instruction":"建立硬度、裂隙、含水與出碴四列需求表，分別說明刀盤、工作面支承、密封與運輸的角色。比較英法兩側條件可能不同的理由，不填操作壓力。","instructionEn":"Create a table for strength, fractures, water and spoil handling; identify cutting, face support, sealing and transport roles. Explain why the two shores may need different configurations without specifying operating pressures.","observation":"觀察「能切削岩石」與「能管理水及出碴」是否是不同能力。","observationEn":"Distinguish ability to cut rock from ability to manage water and spoil.","failure":"只以隧道直徑挑選機台，忽略地層與水壓條件。","failureEn":"Selecting a machine by tunnel diameter alone while ignoring ground and water conditions.","check":"每項功能至少連到一項地質證據或待調查事項。","checkEn":"Link each function to geological evidence or an investigation need.","knowledge":[{"id":"b102-v6-03-k1","title":"適地配置","titleEn":"Ground-specific configuration","text":"同一工程可採用不同配置，以回應各段地層與地下水差異。","textEn":"One project may use different configurations to address sectional ground and groundwater differences."},{"id":"b102-v6-03-k2","title":"連續物流","titleEn":"Continuous logistics","text":"切削、出碴與環片供應互相制約；單一速度不能代表整體能力。","textEn":"Cutting, spoil removal and segment supply constrain one another; one speed does not represent total capability."}],"quiz":{"options":["直徑相同就必須使用相同配置","只需改變列車速度","工作面支承與密封需求仍可能不同"],"optionsEn":["Equal diameter requires identical configuration","Only train speed needs changing","Face-support and sealing requirements may still differ"],"answer":2,"question":"兩段隧道直徑相同但含水條件不同，哪個結論合理？","questionEn":"Two sections share a diameter but differ in water conditions. Which conclusion is reasonable?","explanation":"直徑只是幾何要求；地下水和地層決定另外的功能需求。","explanationEn":"Diameter defines geometry; ground and groundwater impose additional functional requirements."}},{"id":"b102-v6-04","sequence":4,"order":4,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-03"],"title":"用開挖觀察修訂地質模型","titleEn":"Update the ground model from excavation observations","objective":"建立預測與現地觀察不一致時的判讀流程。","objectiveEn":"Define a response when predictions and field observations disagree.","instruction":"自行寫三則示例觀察：出碴性質改變、滲水增加、測量方向偏移。分別列出可能機制、需補查紀錄與模型要修訂的欄位。","instructionEn":"Invent three observations: changed spoil, increased ingress and a survey-direction shift. For each, list candidate mechanisms, records to check and model fields to revise.","observation":"注意相同表徵可以有地質、設備或量測等不同原因。","observationEn":"Recognize that the same symptom may have geological, equipment or measurement causes.","failure":"因原模型標示低透水，就把新增滲水當成量測錯誤刪除。","failureEn":"Discarding increased ingress as measurement error because the original model predicts low permeability.","check":"至少保留兩種競爭假說，並寫出可區分它們的證據。","checkEn":"Retain at least two competing explanations and evidence that could distinguish them.","knowledge":[{"id":"b102-v6-04-k1","title":"觀察回饋","titleEn":"Observational feedback","text":"地質預測應接受新證據檢驗；模型不是現地狀態的保證。","textEn":"Geological predictions must be tested against new evidence; a model does not guarantee field conditions."},{"id":"b102-v6-04-k2","title":"可區分證據","titleEn":"Discriminating evidence","text":"有用的補查應能讓不同假說產生不同預期結果。","textEn":"Useful follow-up evidence produces different expected results under competing explanations."}],"quiz":{"options":["保留原版本，加入新觀察並重新評估","只保留原先最有利的假設","把兩種現象平均成一個正常值"],"optionsEn":["Preserve the old version, add observations and reassess","Retain only the original favorable assumption","Average both symptoms into a normal value"],"answer":0,"question":"出碴變化與新滲水同時發生時，應如何處理模型？","questionEn":"Spoil changes and new water ingress occur together. How should the model be treated?","explanation":"版本化修訂保留決策依據，並讓新增證據改變推論。","explanationEn":"Versioned revision preserves decision context while allowing new evidence to change conclusions."}}],"title":"地質、測量與開挖","titleEn":"Geology, survey and excavation","description":"把預期地層、實際觀察與開挖配置建立可修訂的對照。","descriptionEn":"Build a revisable comparison between expected ground, observations and excavation configuration."},{"id":"b102-stage02","order":2,"steps":[{"id":"b102-v6-05","sequence":5,"order":1,"sourceIds":["v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-04"],"title":"檢查襯砌環與接縫","titleEn":"Review lining rings and joints","objective":"分清承載、防水與幾何接合證據。","objectiveEn":"Separate evidence for load support, water control and geometric fit.","instruction":"畫一圈分片襯砌及相鄰兩環，標記接縫、接觸面與可能漏水路徑。建立環片識別、位置、缺損和接縫觀察的記錄欄位。","instructionEn":"Draw a segmented ring and two adjacent rings, marking joints, contacts and potential ingress paths. Define records for segment identity, location, defects and joint observations.","observation":"比較環片本體完整與接縫完整是否能互相替代。","observationEn":"Ask whether sound segment bodies and sound joints provide interchangeable evidence.","failure":"環片外表沒有裂縫，就認定所有接縫都止水良好。","failureEn":"Assuming every joint is watertight because segment faces have no visible cracks.","check":"為承載、幾何、防水各列一種不同的檢核證據。","checkEn":"Name distinct evidence for support, geometry and water control.","knowledge":[{"id":"b102-v6-05-k1","title":"系統接縫","titleEn":"System joints","text":"襯砌不是孤立環片的集合；環內與環間接合會影響整體性能。","textEn":"Lining behavior depends on within-ring and between-ring joints, not only isolated segments."},{"id":"b102-v6-05-k2","title":"位置追溯","titleEn":"Location traceability","text":"缺陷紀錄須能回到具體環號與方位，才能比較後續變化。","textEn":"Defect records need ring identity and orientation to support later comparisons."}],"quiz":{"options":["全隧道環片總數","同環號、方位及時間的觀察序列","未註位置的零散照片"],"optionsEn":["Total number of tunnel segments","Observations with matching ring, orientation and timestamps","Unlocated photographs"],"answer":1,"question":"哪項記錄最適合追蹤接縫漏水是否擴大？","questionEn":"Which record best tracks whether joint leakage is spreading?","explanation":"可定位、可比較的紀錄才支持變化判斷。","explanationEn":"Located and comparable records support judgments about change."}},{"id":"b102-v6-06","sequence":6,"order":2,"sourceIds":["v6-channel-infrastructure","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-05"],"title":"區分漏水來源與排水路徑","titleEn":"Distinguish ingress sources from drainage paths","objective":"解釋抽排能力不等於止水成功。","objectiveEn":"Explain why pumping capacity does not prove successful water exclusion.","instruction":"自繪接縫、集水溝、集水井和抽排出口，分別用箭頭表示外水進入與收集輸送。以示例時間表比較降雨、漏水位置及抽排量。","instructionEn":"Sketch joints, drains, sumps and discharge, using different arrows for water ingress and collection. Compare rainfall, leak locations and pumping in an invented timeline.","observation":"觀察集水量變化可能來自入流改變，也可能來自排水路徑堵塞。","observationEn":"Changes in collected flow may reflect altered inflow or blocked drainage routes.","failure":"抽水機仍運轉就推論沒有漏水，或流量下降就推論問題改善。","failureEn":"Inferring no ingress because pumps run, or improvement because measured flow falls.","check":"指出兩種使觀測流量下降的不同情境與辨別資料。","checkEn":"Identify two different causes of reduced measured flow and evidence distinguishing them.","knowledge":[{"id":"b102-v6-06-k1","title":"入流與輸送","titleEn":"Inflow versus conveyance","text":"滲入隧道的水與被量測到的排水，可能因蓄積或堵塞而不同。","textEn":"Ingress and measured drainage can differ because of storage or obstruction."},{"id":"b102-v6-06-k2","title":"水量平衡","titleEn":"Water balance","text":"在有明確時間範圍的模型中，入流、出流和蓄積須互相一致。","textEn":"In a time-bounded model, inflow, outflow and storage change must be consistent."}],"quiz":{"options":["只確認供電存在，便排除所有排水問題","直接宣告外水已減少","收集及輸送路徑是否受阻"],"optionsEn":["Confirm supply power and rule out all drainage problems","Immediately conclude external ingress has decreased","Whether collection or conveyance is obstructed"],"answer":2,"question":"排水量下降但局部積水升高，最應檢查什麼？","questionEn":"Drainage flow falls while local ponding rises. What most needs checking?","explanation":"流量與積水相反變化提示輸送問題，需核查路徑和量測。","explanationEn":"Opposing flow and ponding trends suggest a conveyance issue requiring route and measurement checks."}},{"id":"b102-v6-07","sequence":7,"order":3,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-06"],"title":"辨認三條隧道的功能","titleEn":"Distinguish the three tunnel roles","objective":"將交通、維護與避難功能在圖中分開。","objectiveEn":"Separate traffic, maintenance and refuge functions on a diagram.","instruction":"自繪兩條行車隧道和中央服務隧道，再加入聯絡通道。用三種線型表示列車路線、維護通行與示意撤離方向，避免填入真實緊急操作命令。","instructionEn":"Sketch two running tunnels and a central service tunnel with cross-passages. Use distinct line styles for trains, maintenance and illustrative evacuation, without issuing real emergency instructions.","observation":"觀察聯絡通道與供列車換線的橫渡洞室是否是不同構造。","observationEn":"Distinguish pedestrian/service cross-passages from rail crossover caverns.","failure":"把服務隧道畫成第三條正常載客鐵路。","failureEn":"Drawing the service tunnel as a third regular passenger railway.","check":"圖例應能一眼分辨三種功能與兩種橫向連接。","checkEn":"The key must distinguish the three functions and the two types of lateral connection.","knowledge":[{"id":"b102-v6-07-k1","title":"功能隔離","titleEn":"Functional separation","text":"中央服務隧道提供維護與緊急支援，與行車隧道用途不同。","textEn":"The central service tunnel supports maintenance and emergencies rather than normal rail traffic."},{"id":"b102-v6-07-k2","title":"連接類型","titleEn":"Connection types","text":"聯絡通道服務人員移動；橫渡洞室則提供列車跨線能力。","textEn":"Cross-passages support movement of people; crossover caverns allow trains to change running tunnels."}],"quiz":{"options":["設有軌道的橫渡洞室","一般人行聯絡通道","服務隧道內的排水溝"],"optionsEn":["A rail crossover cavern","An ordinary pedestrian cross-passage","A service-tunnel drain"],"answer":0,"question":"需要列車從一條行車隧道移到另一條時，對應哪個構造？","questionEn":"Which structure allows a train to change from one running tunnel to the other?","explanation":"不同橫向連接有不同尺寸和用途，不能在系統圖上混用。","explanationEn":"Different lateral connections serve different functions and must not be conflated."}},{"id":"b102-v6-08","sequence":8,"order":4,"sourceIds":["v6-channel-infrastructure","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-07"],"title":"讀懂服務隧道壓差概念","titleEn":"Interpret service-tunnel pressure differences","objective":"理解保護空間與門、通風的相互依賴。","objectiveEn":"Understand dependencies among protected space, doors and ventilation.","instruction":"以兩個箱體代表服務與行車隧道，畫出正常示意氣流和門開啟時的可能路徑。列出判斷氣流方向需要的資料，不自行設定火災排煙程序。","instructionEn":"Represent service and running tunnels as two boxes. Sketch intended airflow and possible paths when a door opens. List data needed to judge flow without defining fire-smoke operating procedures.","observation":"注意風機狀態、壓差與門的位置並非同一個訊號。","observationEn":"Fan status, pressure difference and door position are different signals.","failure":"只因風機顯示開啟，就認定保護空間一定維持壓差。","failureEn":"Assuming a protected space maintains pressure simply because a fan indicates running.","check":"列出至少三個互相核對的狀態或觀察量。","checkEn":"List at least three states or observations to cross-check.","knowledge":[{"id":"b102-v6-08-k1","title":"壓差屏障","titleEn":"Pressure barrier","text":"適當的壓差可引導氣流；實際效果仍受開口與系統狀態影響。","textEn":"Pressure differences can direct flow; openings and system state affect actual performance."},{"id":"b102-v6-08-k2","title":"功能驗證","titleEn":"Functional verification","text":"設備運转訊號只能證明部分狀態，不能代替完整功能證據。","textEn":"A running indication establishes only part of the state, not complete functional performance."}],"quiz":{"options":["忽略壓差，因馬達已運轉","核對開口、氣流及感測狀態","立即認定所有門都關妥"],"optionsEn":["Ignore pressure because motors are running","Check openings, airflow and sensor state","Assume all doors are properly closed"],"answer":1,"question":"風機開啟但保護區壓差不足，哪個判斷較合理？","questionEn":"Fans run but protected-zone pressure is insufficient. Which judgment is sound?","explanation":"保護功能依賴整體狀態，必須把設備與環境證據合看。","explanationEn":"Protection depends on system state, so equipment and environmental evidence must be combined."}}],"title":"襯砌與三隧道介面","titleEn":"Lining and three-bore interfaces","description":"追蹤環片接合、排水與聯絡通道在不同狀態的功能。","descriptionEn":"Trace segment joints, drainage and cross-passages under different system states."},{"id":"b102-stage03","order":3,"steps":[{"id":"b102-v6-09","sequence":9,"order":1,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-08"],"title":"整理軌道與機電淨空","titleEn":"Coordinate track and service clearances","objective":"看出斷面配置中的安裝與維護衝突。","objectiveEn":"Identify installation and maintenance conflicts in a cross-section.","instruction":"在自繪圓形斷面放入列車包絡、步道、電車線、冷卻管與電纜。再畫一個設備維護所需空間，以虛線標記尚無尺寸資料的部分。","instructionEn":"Place a train envelope, walkway, catenary, cooling pipes and cables in a circular sketch. Add maintenance space and use dashed boundaries where dimensional evidence is missing.","observation":"比較「裝得下」與「仍可檢查、撤離和維護」是否不同。","observationEn":"Distinguish physical fit from retained inspection, egress and maintenance access.","failure":"只畫設備外形，忽略人員通行及拆換路徑。","failureEn":"Drawing equipment outlines without access or replacement paths.","check":"找出兩個潛在介面衝突並列明需向哪個專業取得資料。","checkEn":"Identify two potential conflicts and the disciplines that must provide missing data.","knowledge":[{"id":"b102-v6-09-k1","title":"包絡介面","titleEn":"Envelope interfaces","text":"設備配置須同時考慮車輛動態、結構和通行空間。","textEn":"Equipment layout must account for vehicle motion, structure and access together."},{"id":"b102-v6-09-k2","title":"維護空間","titleEn":"Maintenance space","text":"正常運轉不碰撞，不等於能安全拆換或檢查設備。","textEn":"Collision-free operation does not establish that equipment can be inspected or replaced safely."}],"quiz":{"options":["是，唯一條件是不碰列車","只要管線顏色不同即可","尚未，通行與維護需求仍未滿足"],"optionsEn":["Yes; avoiding the train is the only condition","Yes, if the pipe has a different color","No; access and maintenance requirements remain unresolved"],"answer":2,"question":"一條新管線不碰列車但占用步道，是否已完成介面檢核？","questionEn":"A new pipe avoids the train but occupies the walkway. Is interface review complete?","explanation":"斷面有多種功能包絡，不能只檢查車輛外形。","explanationEn":"The cross-section contains multiple functional envelopes, not only a train outline."}},{"id":"b102-v6-10","sequence":10,"order":2,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-09"],"title":"檢查供電與服務依賴","titleEn":"Review power and service dependencies","objective":"說明冗餘電源不等於所有設備都無中斷。","objectiveEn":"Explain why redundant supplies do not prove uninterrupted service for every load.","instruction":"畫出兩岸電源、供電分段及列車、排水、照明三類負載。以紙上情境移除一個來源，標記哪些功能仍需切換與控制證據。","instructionEn":"Diagram power from both shores, supply sections and train, drainage and lighting loads. Remove one source in a paper scenario and mark functions requiring transfer and control evidence.","observation":"比較電源存在、路徑可用與末端設備運轉三種狀態。","observationEn":"Distinguish source availability, path availability and operation of the final device.","failure":"把圖上有兩個電源直接視為所有故障情況都有備援。","failureEn":"Treating two drawn power sources as proof of redundancy for every failure case.","check":"為一個負載畫出完整替代路徑，並列一個共同失效點的疑問。","checkEn":"Trace an alternative path to one load and identify a possible common failure point.","knowledge":[{"id":"b102-v6-10-k1","title":"端到端功能","titleEn":"End-to-end function","text":"備援需要從來源到負載的完整可用路徑。","textEn":"Redundancy requires a complete available path from source to load."},{"id":"b102-v6-10-k2","title":"共同依賴","titleEn":"Shared dependencies","text":"兩條供電路徑仍可能共用控制、保護或連接設備。","textEn":"Two supply paths may still share control, protection or connection equipment."}],"quiz":{"options":["替代來源到排水設備的整條路徑是否可用","只核對備援來源額定容量，不追蹤配電路徑","以其他負載正常推論排水設備必定可用"],"optionsEn":["Is the complete alternative path to drainage equipment available?","Check backup source rating without tracing distribution","Infer drainage availability because other loads work"],"answer":0,"question":"確認排水備援時，哪個問題最重要？","questionEn":"Which question matters most when verifying drainage backup?","explanation":"功能驗證必須追到負載，不能停在上游電源。","explanationEn":"Verification must reach the load rather than stop at the upstream source."}},{"id":"b102-v6-11","sequence":11,"order":3,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-10"],"title":"組織維護占用與復歸證據","titleEn":"Organize maintenance possession and return evidence","objective":"辨認施工完成與恢復運行間的交接責任。","objectiveEn":"Distinguish completion of work from authorization to resume service.","instruction":"建立示意交接表，含區段、受影響設備、隔離狀態、檢查結果及未結案項。用「換線維護」桌上情境辨認交通與設備團隊的交界，不模擬真實控制指令。","instructionEn":"Build an illustrative handover sheet with section, affected equipment, isolation state, checks and open items. Use a crossover-maintenance tabletop scenario to identify team interfaces without simulating real control commands.","observation":"觀察工件安裝完成是否仍有功能測試與文件核對未完成。","observationEn":"Notice whether physical completion still leaves functional tests or document reconciliation pending.","failure":"以工時結束代替設備復歸與路線交接確認。","failureEn":"Treating the end of a work shift as confirmation of equipment restoration and route handover.","check":"將施工完成、測試完成與授權狀態分成獨立欄位。","checkEn":"Keep work completion, test completion and authorization state in separate fields.","knowledge":[{"id":"b102-v6-11-k1","title":"狀態交接","titleEn":"State handover","text":"跨班或跨專業交接應描述實際設備狀態及尚未解除的限制。","textEn":"Cross-shift or cross-discipline handover must describe actual equipment state and remaining restrictions."},{"id":"b102-v6-11-k2","title":"責任邊界","titleEn":"Responsibility boundaries","text":"驗證證據與運行授權由不同角色承擔時，介面必須清楚。","textEn":"Interfaces must be explicit when verification and operating authority belong to different roles."}],"quiz":{"options":["直接填寫已全面復歸","機械完成與功能未驗證分別列示","刪除測試欄以免混淆"],"optionsEn":["Mark fully restored","Record mechanical completion and unverified function separately","Remove the test field"],"answer":1,"question":"工件已裝回但功能測試未完成，交接表應如何表示？","questionEn":"A component is reinstalled but functional testing is incomplete. How should it be recorded?","explanation":"不同完成層次不能互相替代，否則會掩蓋未結案工作。","explanationEn":"Different completion levels are not interchangeable and must not hide unfinished work."}},{"id":"b102-v6-12","sequence":12,"order":4,"sourceIds":["v6-channel-infrastructure","v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-11"],"title":"交付三隧道整合模型","titleEn":"Deliver the integrated three-bore model","objective":"將土建與機電證據連成可查核的系統。","objectiveEn":"Connect civil and service-system evidence into an auditable model.","instruction":"把地質、襯砌、漏水、通風和供電圖表整理成同一介面索引。選一個「供電中斷伴隨滲水」假想情境，指出需聯合查證的兩個系統與資料缺口。","instructionEn":"Index ground, lining, ingress, ventilation and power records together. For an invented power-loss-plus-ingress scenario, identify two systems requiring joint review and remaining evidence gaps.","observation":"檢查每個功能主張是否有可定位的圖表或紀錄支持。","observationEn":"Check that each functional claim has a located diagram or record behind it.","failure":"各專業圖表單獨完整，卻無法對齊區段名稱與狀態。","failureEn":"Individually complete discipline records cannot be reconciled by location or state.","check":"提交共享區段索引、假設清單與至少三項未解介面問題。","checkEn":"Submit a common section index, assumptions and at least three unresolved interface questions.","knowledge":[{"id":"b102-v6-12-k1","title":"系統整合","titleEn":"Systems integration","text":"隧道能否服務取決於土建、設備、交通與維護的共同狀態。","textEn":"Tunnel service depends on combined civil, equipment, traffic and maintenance states."},{"id":"b102-v6-12-k2","title":"共同識別","titleEn":"Common identifiers","text":"一致的區段與設備識別可防止把不同位置的證據錯接。","textEn":"Consistent section and equipment identifiers prevent mismatching evidence from different locations."}],"quiz":{"options":["只核對總設備數量是否相同","只比較各自最後一次正常結果","區段、設備識別、時間及狀態"],"optionsEn":["Whether total equipment counts match","Compare only each system’s latest normal result","Section, equipment identity, time and state"],"answer":2,"question":"整合兩份排水與供電紀錄前，最先應核對什麼？","questionEn":"What should first be reconciled when integrating drainage and power records?","explanation":"共同識別與時間狀態使不同專業證據可以正確連結。","explanationEn":"Shared identifiers and time/state information allow evidence from different disciplines to be connected correctly."}}],"title":"機電整合與交付","titleEn":"Systems integration and handover","description":"以桌上情境檢查通風、供電、交通和維護的依賴。","descriptionEn":"Use tabletop scenarios to review dependencies among ventilation, power, traffic and maintenance."},{"id":"b102-v14-s1","title":"地層條件、邊界與工程系統","titleEn":"Ground conditions, boundaries and engineering system","description":"本階段聚焦「測壓水頭與襯砌外壓」與「環向受力與接縫柔度」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Piezometric head and lining pressure\" and \"Ring force and joint flexibility\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b102-v14-01","title":"測壓水頭與襯砌外壓：機制與系統路徑","titleEn":"Piezometric head and lining pressure: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v6-12"],"objective":"說明「測壓水頭」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Piezometric head” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"英法海底案例先區分海面水深與岩層測壓水頭，避免把海床幾何直接當襯砌各處水壓；服務通道排水也會影響局部梯度。水壓取決於連通含水層的測壓水頭，不必等於地表或海面至洞頂的幾何深度。排水降低水壓卻可能增加有效應力與沉陷；停泵或排水堵塞後水頭又會回升，因此防水、排水及環境保水是互相制約的設計選擇。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「測壓水頭」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Distinguish seawater depth from rock piezometric head, including local gradients affected by service-gallery drainage rather than equating seabed geometry with pressure everywhere. Water pressure follows piezometric head in the connected aquifer, not automatically the geometric depth below ground or sea level. Drainage reduces pressure but can increase effective stress and settlement. Head may recover after a pump outage or blockage, coupling waterproofing, drainage capacity and preservation of surrounding groundwater in the permanent design. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Piezometric head” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：水密度=1000 kg/m³；水頭=34 m。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: water density=1000 kg/m³; head=34 m. p=ρgh/1000, g=9.81 m/s²=333.54 kPa.","failure":"常見誤解：「目前沒有可見漏水就能在設計中忽略外水壓。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"No visible leakage means that external water pressure can be omitted from design.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「測壓水頭」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Piezometric head”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-01-k1","title":"測壓水頭與襯砌外壓","titleEn":"Piezometric head and lining pressure","text":"英法海底案例先區分海面水深與岩層測壓水頭，避免把海床幾何直接當襯砌各處水壓；服務通道排水也會影響局部梯度。水壓取決於連通含水層的測壓水頭，不必等於地表或海面至洞頂的幾何深度。","textEn":"Distinguish seawater depth from rock piezometric head, including local gradients affected by service-gallery drainage rather than equating seabed geometry with pressure everywhere. Water pressure follows piezometric head in the connected aquifer, not automatically the geometric depth below ground or sea level.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：目前沒有可見漏水就能在設計中忽略外水壓。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: No visible leakage means that external water pressure can be omitted from design. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「測壓水頭與襯砌外壓」，下列哪一項敘述正確？","questionEn":"Which statement about \"Piezometric head and lining pressure\" is correct?","options":["目前沒有可見漏水就能在設計中忽略外水壓。","英法海底案例先區分海面水深與岩層測壓水頭，避免把海床幾何直接當襯砌各處水壓；服務通道排水也會影響局部梯度。","混凝土強度達標就不必檢查接縫轉動與偏壓。"],"optionsEn":["No visible leakage means that external water pressure can be omitted from design.","Distinguish seawater depth from rock piezometric head, including local gradients affected by service-gallery drainage rather than equating seabed geometry with pressure everywhere.","Passing concrete strength eliminates the need to check joint rotation and uneven pressure."],"answer":1,"explanation":"英法海底案例先區分海面水深與岩層測壓水頭，避免把海床幾何直接當襯砌各處水壓；服務通道排水也會影響局部梯度。 其餘選項是常見誤解。","explanationEn":"Distinguish seawater depth from rock piezometric head, including local gradients affected by service-gallery drainage rather than equating seabed geometry with pressure everywhere. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":13},{"id":"b102-v14-02","title":"測壓水頭與襯砌外壓：定量估算","titleEn":"Piezometric head and lining pressure: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-01"],"objective":"以數值模型估算「測壓水頭」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Piezometric head” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：水密度=1000 kg/m³；水頭=34 m。p=ρgh/1000, g=9.81 m/s²=333.54 kPa。僅把水頭增加10%，其他條件不變，重算為366.894 kPa。邊界：靜水表壓，不是土體總壓或原位量測；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: water density=1000 kg/m³; head=34 m. p=ρgh/1000, g=9.81 m/s²=333.54 kPa. Increasing only head by 10% with all other inputs fixed gives 366.894 kPa. Boundary: Hydrostatic gauge pressure, not total earth pressure or an in-situ measurement. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將主孔與服務孔測壓點用同一高程和潮位基準比較，檢查水頭相位差是否支持連通假設。","observationEn":"How to cross-check: Compare bore and service-gallery piezometers on one elevation and tide datum, testing whether phase differences support hydraulic connectivity.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：水密度=1000 kg/m³；水頭=34 m。p=ρgh/1000, g=9.81 m/s²=333.54 kPa。僅把水頭增加10%，其他條件不變，重算為366.894 kPa。邊界：靜水表壓，不是土體總壓或原位量測；不是本工程實測或允收值。","textEn":"Original teaching assumptions: water density=1000 kg/m³; head=34 m. p=ρgh/1000, g=9.81 m/s²=333.54 kPa. Increasing only head by 10% with all other inputs fixed gives 366.894 kPa. Boundary: Hydrostatic gauge pressure, not total earth pressure or an in-situ measurement. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「測壓水頭與襯砌外壓」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Piezometric head and lining pressure\", which statement holds?","options":["增加工作面就可以直接把各面的理論產量相加。","動壓公式算出的數值就是長鐵路隧道完整壓力波。","原創教學假設：水密度=1000 kg/m³；水頭=34 m。"],"optionsEn":["Adding headings allows their theoretical outputs to be summed directly.","A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.","Original teaching assumptions: water density=1000 kg/m³; head=34 m. p=ρgh/1000, g=9.81 m/s²=333.54 kPa."],"answer":2,"explanation":"原創教學假設：水密度=1000 kg/m³；水頭=34 m。 重算時請保留單位。","explanationEn":"Original teaching assumptions: water density=1000 kg/m³; head=34 m. p=ρgh/1000, g=9.81 m/s²=333.54 kPa. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":14},{"id":"b102-v14-03","title":"測壓水頭與襯砌外壓：試驗與驗證","titleEn":"Piezometric head and lining pressure: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「測壓水頭」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Piezometric head” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將主孔與服務孔測壓點用同一高程和潮位基準比較，檢查水頭相位差是否支持連通假設。使用分層測壓管及流量計，配合降雨或潮位序列分辨補注與設備影響，將讀值統一換算至同一高程基準。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare bore and service-gallery piezometers on one elevation and tide datum, testing whether phase differences support hydraulic connectivity. Use nested piezometers and flowmeters with rainfall or tide histories to distinguish recharge from equipment effects, converting observations to a common elevation datum. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「測壓水頭」的交付需回答：將主孔與服務孔測壓點用同一高程和潮位基準比較，檢查水頭相位差是否支持連通假設。設計檢核應分列正常排水、堵塞與停電水位，將環境受體的容許變化和監測責任一起交付，不把抽水量當唯一指標。","observationEn":"Site practice: For Channel Tunnel, the piezometric head handover must address the following evidence: Compare bore and service-gallery piezometers on one elevation and tide datum, testing whether phase differences support hydraulic connectivity. Separate normal drainage, blocked-drain and power-outage heads and hand over receptor limits and monitoring responsibility together rather than using pump flow as the sole indicator.","failure":"注意干擾：潮汐反應滯後若當成儀器故障，會錯過含水層傳遞時間與排水邊界變化。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Mistaking tidal lag for sensor failure loses information about aquifer response time and drainage-boundary changes. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-03-k1","title":"驗證方法","titleEn":"Verification method","text":"將主孔與服務孔測壓點用同一高程和潮位基準比較，檢查水頭相位差是否支持連通假設。使用分層測壓管及流量計，配合降雨或潮位序列分辨補注與設備影響，將讀值統一換算至同一高程基準。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Compare bore and service-gallery piezometers on one elevation and tide datum, testing whether phase differences support hydraulic connectivity. Use nested piezometers and flowmeters with rainfall or tide histories to distinguish recharge from equipment effects, converting observations to a common elevation datum. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-03-k2","title":"現場實務","titleEn":"Site practice","text":"本案「測壓水頭」的交付需回答：將主孔與服務孔測壓點用同一高程和潮位基準比較，檢查水頭相位差是否支持連通假設。設計檢核應分列正常排水、堵塞與停電水位，將環境受體的容許變化和監測責任一起交付，不把抽水量當唯一指標。","textEn":"For Channel Tunnel, the piezometric head handover must address the following evidence: Compare bore and service-gallery piezometers on one elevation and tide datum, testing whether phase differences support hydraulic connectivity. Separate normal drainage, blocked-drain and power-outage heads and hand over receptor limits and monitoring responsibility together rather than using pump flow as the sole indicator.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「測壓水頭與襯砌外壓」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Piezometric head and lining pressure\"?","options":["將主孔與服務孔測壓點用同一高程和潮位基準比較，檢查水頭相位差是否支持連通假設。","量測時不必記錄溫度、水頭、開挖序列與施工荷重，因為它們不會影響結果。","集水坑總容積除以平均入流就是保證可用的反應時間。"],"optionsEn":["Compare bore and service-gallery piezometers on one elevation and tide datum, testing whether phase differences support hydraulic connectivity.","Temperature, water head, excavation sequence and construction loads need not be recorded because they cannot affect the result.","Gross sump volume divided by average inflow is a guaranteed response time."],"answer":0,"explanation":"將主孔與服務孔測壓點用同一高程和潮位基準比較，檢查水頭相位差是否支持連通假設。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare bore and service-gallery piezometers on one elevation and tide datum, testing whether phase differences support hydraulic connectivity. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":15},{"id":"b102-v14-04","title":"測壓水頭與襯砌外壓：失效診斷","titleEn":"Piezometric head and lining pressure: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-03"],"objective":"從症狀倒推「測壓水頭」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Piezometric head” and propose discriminating checks, corrective actions and prevention.","instruction":"潮汐反應滯後若當成儀器故障，會錯過含水層傳遞時間與排水邊界變化。將暫時降水後的低水頭當成永久狀態，會漏掉停泵後外壓回升；過度排水也可能引起周邊地層壓密。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Mistaking tidal lag for sensor failure loses information about aquifer response time and drainage-boundary changes. Treating temporarily lowered head as permanent misses pressure recovery after outage; excessive drainage can also consolidate surrounding ground. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：排水降低水壓卻可能增加有效應力與沉陷；停泵或排水堵塞後水頭又會回升，因此防水、排水及環境保水是互相制約的設計選擇。","observationEn":"Link to the mechanism: Head may recover after a pump outage or blockage, coupling waterproofing, drainage capacity and preservation of surrounding groundwater in the permanent design.","failure":"誤判風險：若相信「目前沒有可見漏水就能在設計中忽略外水壓。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"No visible leakage means that external water pressure can be omitted from design.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-04-k1","title":"失效模式","titleEn":"Failure mode","text":"潮汐反應滯後若當成儀器故障，會錯過含水層傳遞時間與排水邊界變化。將暫時降水後的低水頭當成永久狀態，會漏掉停泵後外壓回升；過度排水也可能引起周邊地層壓密。","textEn":"Mistaking tidal lag for sensor failure loses information about aquifer response time and drainage-boundary changes. Treating temporarily lowered head as permanent misses pressure recovery after outage; excessive drainage can also consolidate surrounding ground.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「測壓水頭與襯砌外壓」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Piezometric head and lining pressure\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","潮汐反應滯後若當成儀器故障，會錯過含水層傳遞時間與排水邊界變化。","混凝土強度達標就不必檢查接縫轉動與偏壓。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Mistaking tidal lag for sensor failure loses information about aquifer response time and drainage-boundary changes.","Passing concrete strength eliminates the need to check joint rotation and uneven pressure."],"answer":1,"explanation":"潮汐反應滯後若當成儀器故障，會錯過含水層傳遞時間與排水邊界變化。 需以量測區分可能原因。","explanationEn":"Mistaking tidal lag for sensor failure loses information about aquifer response time and drainage-boundary changes. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":16},{"id":"b102-v14-05","title":"環向受力與接縫柔度：機制與系統路徑","titleEn":"Ring force and joint flexibility: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-04"],"objective":"說明「襯砌環向壓縮」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Lining hoop compression” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"比較英法主孔及服務通道的襯砌尺度，幾何縮小雖改變膜應力量級，接頭轉角、局部荷載及維修開口仍須獨立評估。圓形襯砌對均勻外壓可主要以環向壓縮抵抗，但接頭轉動、偏壓與背填空隙會引起彎矩。薄環膜應力只說明其中一條受力路徑；脫模、運輸、頂推及永久狀態的荷載不同，環片局部接觸與止水條件必須另外檢核。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「襯砌環向壓縮」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Compare lining scales in running bores and service access; geometric scaling changes membrane stress but does not preserve joint rotations, local loads or maintenance-opening behaviour. A circular lining resists uniform external pressure largely through hoop compression, but joint rotation, uneven load and backfill voids generate bending. Thin-ring membrane stress describes only one load path. Demoulding, transport, jacking and permanent states impose different actions, requiring separate checks of local segment contact and sealing rather than one permanent-load calculation. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Lining hoop compression” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：均勻外壓=0.32 MPa；半徑=3.1 m；厚度=0.35 m。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: uniform external pressure=0.32 MPa; radius=3.1 m; thickness=0.35 m. σθ=pr/t=2.83429 MPa.","failure":"常見誤解：「混凝土強度達標就不必檢查接縫轉動與偏壓。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Passing concrete strength eliminates the need to check joint rotation and uneven pressure.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「襯砌環向壓縮」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Lining hoop compression”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-05-k1","title":"環向受力與接縫柔度","titleEn":"Ring force and joint flexibility","text":"比較英法主孔及服務通道的襯砌尺度，幾何縮小雖改變膜應力量級，接頭轉角、局部荷載及維修開口仍須獨立評估。圓形襯砌對均勻外壓可主要以環向壓縮抵抗，但接頭轉動、偏壓與背填空隙會引起彎矩。","textEn":"Compare lining scales in running bores and service access; geometric scaling changes membrane stress but does not preserve joint rotations, local loads or maintenance-opening behaviour. A circular lining resists uniform external pressure largely through hoop compression, but joint rotation, uneven load and backfill voids generate bending.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：混凝土強度達標就不必檢查接縫轉動與偏壓。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Passing concrete strength eliminates the need to check joint rotation and uneven pressure. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「環向受力與接縫柔度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Ring force and joint flexibility\" is correct?","options":["混凝土強度達標就不必檢查接縫轉動與偏壓。","接縫平均寬度合格就不必量測局部錯台及扭轉。","比較英法主孔及服務通道的襯砌尺度，幾何縮小雖改變膜應力量級，接頭轉角、局部荷載及維修開口仍須獨立評估。"],"optionsEn":["Passing concrete strength eliminates the need to check joint rotation and uneven pressure.","An acceptable average joint width makes local offset and twist measurements unnecessary.","Compare lining scales in running bores and service access."],"answer":2,"explanation":"比較英法主孔及服務通道的襯砌尺度，幾何縮小雖改變膜應力量級，接頭轉角、局部荷載及維修開口仍須獨立評估。 其餘選項是常見誤解。","explanationEn":"Compare lining scales in running bores and service access; geometric scaling changes membrane stress but does not preserve joint rotations, local loads or maintenance-opening behaviour. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":17},{"id":"b102-v14-06","title":"環向受力與接縫柔度：定量估算","titleEn":"Ring force and joint flexibility: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-05"],"objective":"以數值模型估算「襯砌環向壓縮」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Lining hoop compression” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：均勻外壓=0.32 MPa；半徑=3.1 m；厚度=0.35 m。σθ=pr/t=2.83429 MPa。僅把均勻外壓增加10%，其他條件不變，重算為3.11771 MPa。邊界：薄圓環膜應力，不是接縫、偏壓或矩形框架解；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: uniform external pressure=0.32 MPa; radius=3.1 m; thickness=0.35 m. σθ=pr/t=2.83429 MPa. Increasing only uniform external pressure by 10% with all other inputs fixed gives 3.11771 MPa. Boundary: Thin circular-ring membrane stress, not a joint, uneven-load or rectangular-frame solution. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：分別建立兩種斷面的接頭模型，將同水頭下環向變形與開口附近局部應變對照。","observationEn":"How to cross-check: Model both jointed sections separately and compare circumferential movement with local strains near openings under matched head.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：均勻外壓=0.32 MPa；半徑=3.1 m；厚度=0.35 m。σθ=pr/t=2.83429 MPa。僅把均勻外壓增加10%，其他條件不變，重算為3.11771 MPa。邊界：薄圓環膜應力，不是接縫、偏壓或矩形框架解；不是本工程實測或允收值。","textEn":"Original teaching assumptions: uniform external pressure=0.32 MPa; radius=3.1 m; thickness=0.35 m. σθ=pr/t=2.83429 MPa. Increasing only uniform external pressure by 10% with all other inputs fixed gives 3.11771 MPa. Boundary: Thin circular-ring membrane stress, not a joint, uneven-load or rectangular-frame solution. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「環向受力與接縫柔度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Ring force and joint flexibility\", which statement holds?","options":["原創教學假設：均勻外壓=0.32 MPa；半徑=3.1 m；厚度=0.35 m。","只要體積風量相同，不同海拔的空氣散熱量一定相同。","只要出口距離短，就不需要比較可用與所需安全時間。"],"optionsEn":["Original teaching assumptions: uniform external pressure=0.32 MPa; radius=3.1 m; thickness=0.35 m. σθ=pr/t=2.83429 MPa.","Equal volumetric airflow provides identical cooling at every altitude.","Short exit distance removes the need to compare available and required safe time."],"answer":0,"explanation":"原創教學假設：均勻外壓=0.32 MPa；半徑=3.1 m；厚度=0.35 m。 重算時請保留單位。","explanationEn":"Original teaching assumptions: uniform external pressure=0.32 MPa; radius=3.1 m; thickness=0.35 m. σθ=pr/t=2.83429 MPa. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":18},{"id":"b102-v14-07","title":"環向受力與接縫柔度：試驗與驗證","titleEn":"Ring force and joint flexibility: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「襯砌環向壓縮」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Lining hoop compression” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"分別建立兩種斷面的接頭模型，將同水頭下環向變形與開口附近局部應變對照。將環形變形、接縫張開與應變和含接頭彈簧的模型比較，分開安裝後、背填後及水頭回升後的基準。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Model both jointed sections separately and compare circumferential movement with local strains near openings under matched head. Compare ring distortion, joint opening and strain with a joint-spring model, separating baselines after installation, grouting and head recovery. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「襯砌環向壓縮」的交付需回答：分別建立兩種斷面的接頭模型，將同水頭下環向變形與開口附近局部應變對照。設計圖應分開標註各施工階段、接頭剛度及背填條件，構件驗收同時核對幾何、材料批次與止水試驗適用包絡。","observationEn":"Site practice: For Channel Tunnel, the lining hoop compression handover must address the following evidence: Model both jointed sections separately and compare circumferential movement with local strains near openings under matched head. Drawings distinguish stages, joint stiffness and backfill conditions; component acceptance reconciles geometry, material batches and the applicable sealing-test envelope.","failure":"注意干擾：把小孔的接縫性能按比例套到大孔，可能忽略更大的絕對張開和局部偏心。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Scaling small-bore sealing performance to the larger bore can miss increased absolute opening and local eccentricity. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-07-k1","title":"驗證方法","titleEn":"Verification method","text":"分別建立兩種斷面的接頭模型，將同水頭下環向變形與開口附近局部應變對照。將環形變形、接縫張開與應變和含接頭彈簧的模型比較，分開安裝後、背填後及水頭回升後的基準。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Model both jointed sections separately and compare circumferential movement with local strains near openings under matched head. Compare ring distortion, joint opening and strain with a joint-spring model, separating baselines after installation, grouting and head recovery. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-07-k2","title":"現場實務","titleEn":"Site practice","text":"本案「襯砌環向壓縮」的交付需回答：分別建立兩種斷面的接頭模型，將同水頭下環向變形與開口附近局部應變對照。設計圖應分開標註各施工階段、接頭剛度及背填條件，構件驗收同時核對幾何、材料批次與止水試驗適用包絡。","textEn":"For Channel Tunnel, the lining hoop compression handover must address the following evidence: Model both jointed sections separately and compare circumferential movement with local strains near openings under matched head. Drawings distinguish stages, joint stiffness and backfill conditions; component acceptance reconciles geometry, material batches and the applicable sealing-test envelope.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「環向受力與接縫柔度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Ring force and joint flexibility\"?","options":["沿用另一條隧道或另一處地層的量測結果，就可視為本工程已完成驗證。","分別建立兩種斷面的接頭模型，將同水頭下環向變形與開口附近局部應變對照。","設備有兩台就可以直接把各自故障率相乘判定安全。"],"optionsEn":["Reusing results from another tunnel or ground formation counts as verifying this structure.","Model both jointed sections separately and compare circumferential movement with local strains near openings under matched head.","Two units allow their failure probabilities to be multiplied directly to establish safety."],"answer":1,"explanation":"分別建立兩種斷面的接頭模型，將同水頭下環向變形與開口附近局部應變對照。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Model both jointed sections separately and compare circumferential movement with local strains near openings under matched head. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":19},{"id":"b102-v14-08","title":"環向受力與接縫柔度：失效診斷","titleEn":"Ring force and joint flexibility: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-07"],"objective":"從症狀倒推「襯砌環向壓縮」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Lining hoop compression” and propose discriminating checks, corrective actions and prevention.","instruction":"把小孔的接縫性能按比例套到大孔，可能忽略更大的絕對張開和局部偏心。局部脫空增加環片彎曲，裂縫未必代表混凝土平均強度不足；忽略接縫接觸會把補強方向導向錯誤位置。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Scaling small-bore sealing performance to the larger bore can miss increased absolute opening and local eccentricity. Local voids increase bending, so cracks need not indicate inadequate mean concrete strength; neglecting joint contact can misdirect strengthening. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：薄環膜應力只說明其中一條受力路徑；脫模、運輸、頂推及永久狀態的荷載不同，環片局部接觸與止水條件必須另外檢核。","observationEn":"Link to the mechanism: Demoulding, transport, jacking and permanent states impose different actions, requiring separate checks of local segment contact and sealing rather than one permanent-load calculation.","failure":"誤判風險：若相信「混凝土強度達標就不必檢查接縫轉動與偏壓。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Passing concrete strength eliminates the need to check joint rotation and uneven pressure.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-08-k1","title":"失效模式","titleEn":"Failure mode","text":"把小孔的接縫性能按比例套到大孔，可能忽略更大的絕對張開和局部偏心。局部脫空增加環片彎曲，裂縫未必代表混凝土平均強度不足；忽略接縫接觸會把補強方向導向錯誤位置。","textEn":"Scaling small-bore sealing performance to the larger bore can miss increased absolute opening and local eccentricity. Local voids increase bending, so cracks need not indicate inadequate mean concrete strength; neglecting joint contact can misdirect strengthening.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「環向受力與接縫柔度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Ring force and joint flexibility\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","接縫平均寬度合格就不必量測局部錯台及扭轉。","把小孔的接縫性能按比例套到大孔，可能忽略更大的絕對張開和局部偏心。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","An acceptable average joint width makes local offset and twist measurements unnecessary.","Scaling small-bore sealing performance to the larger bore can miss increased absolute opening and local eccentricity."],"answer":2,"explanation":"把小孔的接縫性能按比例套到大孔，可能忽略更大的絕對張開和局部偏心。 需以量測區分可能原因。","explanationEn":"Scaling small-bore sealing performance to the larger bore can miss increased absolute opening and local eccentricity. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":20}],"order":4},{"id":"b102-v14-s2","title":"機制、材料與定量設計","titleEn":"Mechanisms, materials and quantitative design","description":"本階段聚焦「接頭壓縮與水密包絡」與「共享通道與運輸瓶頸」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Joint compression and sealing envelope\" and \"Shared access and transport bottlenecks\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b102-v14-09","title":"接頭壓縮與水密包絡：機制與系統路徑","titleEn":"Joint compression and sealing envelope: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-08"],"objective":"說明「止水壓縮餘量」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Gasket compression reserve” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"服務通道與主孔間的連接令止水介面不只沿圓環分布，教學比較規則接縫和分岔部位的變形相容，不能只按平均寬度分類。止水條依受控壓縮維持連續接觸，接縫轉角、錯台、污染與材料鬆弛都會降低最不利點的接觸能力。平均壓縮量不能掩蓋局部脫離；全尺寸試驗的結果只對測試過的幾何、水壓及荷載歷程有效，幾何餘量本身並不是接觸壓力。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「止水壓縮餘量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Connections between service access and running bores create nonuniform interfaces; compare regular joints with branch movement compatibility rather than classifying seals by mean gap alone. A gasket seals through controlled continuous compression; rotation, offset, contamination and relaxation reduce contact at the weakest point. Average compression cannot compensate for local separation. Full-size test results apply only to their tested geometry, head and load history, while a calculated geometric reserve is neither contact pressure nor evidence of watertightness. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Gasket compression reserve” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：初始壓縮=19 mm；張開量=3.4 mm；幾何公差=2 mm。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: initial compression=19 mm; opening=3.4 mm; tolerance=2 mm. c_res=c0−opening−tolerance=13.6 mm.","failure":"常見誤解：「接縫平均寬度合格就不必量測局部錯台及扭轉。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"An acceptable average joint width makes local offset and twist measurements unnecessary.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「止水壓縮餘量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Gasket compression reserve”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-09-k1","title":"接頭壓縮與水密包絡","titleEn":"Joint compression and sealing envelope","text":"服務通道與主孔間的連接令止水介面不只沿圓環分布，教學比較規則接縫和分岔部位的變形相容，不能只按平均寬度分類。止水條依受控壓縮維持連續接觸，接縫轉角、錯台、污染與材料鬆弛都會降低最不利點的接觸能力。","textEn":"Connections between service access and running bores create nonuniform interfaces; compare regular joints with branch movement compatibility rather than classifying seals by mean gap alone. A gasket seals through controlled continuous compression; rotation, offset, contamination and relaxation reduce contact at the weakest point.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：接縫平均寬度合格就不必量測局部錯台及扭轉。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: An acceptable average joint width makes local offset and twist measurements unnecessary. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「接頭壓縮與水密包絡」，下列哪一項敘述正確？","questionEn":"Which statement about \"Joint compression and sealing envelope\" is correct?","options":["服務通道與主孔間的連接令止水介面不只沿圓環分布，教學比較規則接縫和分岔部位的變形相容，不能只按平均寬度分類。","接縫平均寬度合格就不必量測局部錯台及扭轉。","增加工作面就可以直接把各面的理論產量相加。"],"optionsEn":["Connections between service access and running bores create nonuniform interfaces.","An acceptable average joint width makes local offset and twist measurements unnecessary.","Adding headings allows their theoretical outputs to be summed directly."],"answer":0,"explanation":"服務通道與主孔間的連接令止水介面不只沿圓環分布，教學比較規則接縫和分岔部位的變形相容，不能只按平均寬度分類。 其餘選項是常見誤解。","explanationEn":"Connections between service access and running bores create nonuniform interfaces; compare regular joints with branch movement compatibility rather than classifying seals by mean gap alone. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":21},{"id":"b102-v14-10","title":"接頭壓縮與水密包絡：定量估算","titleEn":"Joint compression and sealing envelope: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-09"],"objective":"以數值模型估算「止水壓縮餘量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Gasket compression reserve” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：初始壓縮=19 mm；張開量=3.4 mm；幾何公差=2 mm。c_res=c0−opening−tolerance=13.6 mm。僅把張開量增加10%，其他條件不變，重算為13.26 mm。邊界：單向幾何餘量，不是接觸壓或水密合格證明；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: initial compression=19 mm; opening=3.4 mm; tolerance=2 mm. c_res=c0−opening−tolerance=13.6 mm. Increasing only opening by 10% with all other inputs fixed gives 13.26 mm. Boundary: One-direction geometric reserve, not contact pressure or proof of watertightness. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在接縫轉角及分岔附近保存錯台方向，選全尺寸測試中真正對應的組合，而非只比水壓。","observationEn":"How to cross-check: Retain offset direction at rotated and branched interfaces and select the matching full-size test combination, not pressure alone.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：初始壓縮=19 mm；張開量=3.4 mm；幾何公差=2 mm。c_res=c0−opening−tolerance=13.6 mm。僅把張開量增加10%，其他條件不變，重算為13.26 mm。邊界：單向幾何餘量，不是接觸壓或水密合格證明；不是本工程實測或允收值。","textEn":"Original teaching assumptions: initial compression=19 mm; opening=3.4 mm; tolerance=2 mm. c_res=c0−opening−tolerance=13.6 mm. Increasing only opening by 10% with all other inputs fixed gives 13.26 mm. Boundary: One-direction geometric reserve, not contact pressure or proof of watertightness. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「接頭壓縮與水密包絡」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Joint compression and sealing envelope\", which statement holds?","options":["動壓公式算出的數值就是長鐵路隧道完整壓力波。","原創教學假設：初始壓縮=19 mm；張開量=3.4 mm；幾何公差=2 mm。","集水坑總容積除以平均入流就是保證可用的反應時間。"],"optionsEn":["A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.","Original teaching assumptions: initial compression=19 mm; opening=3.4 mm; tolerance=2 mm. c_res=c0−opening−tolerance=13.6 mm.","Gross sump volume divided by average inflow is a guaranteed response time."],"answer":1,"explanation":"原創教學假設：初始壓縮=19 mm；張開量=3.4 mm；幾何公差=2 mm。 重算時請保留單位。","explanationEn":"Original teaching assumptions: initial compression=19 mm; opening=3.4 mm; tolerance=2 mm. c_res=c0−opening−tolerance=13.6 mm. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":22},{"id":"b102-v14-11","title":"接頭壓縮與水密包絡：試驗與驗證","titleEn":"Joint compression and sealing envelope: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「止水壓縮餘量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Gasket compression reserve” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在接縫轉角及分岔附近保存錯台方向，選全尺寸測試中真正對應的組合，而非只比水壓。全尺寸接頭試驗分別改變張開、錯台與外水壓，記錄漏水起點與卸載後殘餘位移，對照材料批次及溫度。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Retain offset direction at rotated and branched interfaces and select the matching full-size test combination, not pressure alone. Vary opening, offset and pressure in full-size joint tests, recording leakage onset and residual movement against material batch and temperature. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「止水壓縮餘量」的交付需回答：在接縫轉角及分岔附近保存錯台方向，選全尺寸測試中真正對應的組合，而非只比水壓。保存接縫幾何與試驗壓力的配對紀錄，由設計者核定允收包絡；驗收時不能把課堂的幾何餘量當產品認證數字。","observationEn":"Site practice: For Channel Tunnel, the gasket compression reserve handover must address the following evidence: Retain offset direction at rotated and branched interfaces and select the matching full-size test combination, not pressure alone. Retain paired joint geometry and test pressure, with the designer approving the acceptance envelope; classroom geometric reserves are not product certification values.","failure":"注意干擾：不同方向錯台可能讓密封接觸區遷移，單一正向試驗合格不能證明反向循環後仍水密。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Opposite offsets can shift the sealing contact zone; passing one-direction tests does not prove tightness after reversed cycles. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-11-k1","title":"驗證方法","titleEn":"Verification method","text":"在接縫轉角及分岔附近保存錯台方向，選全尺寸測試中真正對應的組合，而非只比水壓。全尺寸接頭試驗分別改變張開、錯台與外水壓，記錄漏水起點與卸載後殘餘位移，對照材料批次及溫度。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Retain offset direction at rotated and branched interfaces and select the matching full-size test combination, not pressure alone. Vary opening, offset and pressure in full-size joint tests, recording leakage onset and residual movement against material batch and temperature. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-11-k2","title":"現場實務","titleEn":"Site practice","text":"本案「止水壓縮餘量」的交付需回答：在接縫轉角及分岔附近保存錯台方向，選全尺寸測試中真正對應的組合，而非只比水壓。保存接縫幾何與試驗壓力的配對紀錄，由設計者核定允收包絡；驗收時不能把課堂的幾何餘量當產品認證數字。","textEn":"For Channel Tunnel, the gasket compression reserve handover must address the following evidence: Retain offset direction at rotated and branched interfaces and select the matching full-size test combination, not pressure alone. Retain paired joint geometry and test pressure, with the designer approving the acceptance envelope; classroom geometric reserves are not product certification values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「接頭壓縮與水密包絡」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Joint compression and sealing envelope\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","全部檔案上傳完成就代表工程交接已經驗收合格。","在接縫轉角及分岔附近保存錯台方向，選全尺寸測試中真正對應的組合，而非只比水壓。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Uploading all files means that engineering handover has been accepted.","Retain offset direction at rotated and branched interfaces and select the matching full-size test combination, not pressure alone."],"answer":2,"explanation":"在接縫轉角及分岔附近保存錯台方向，選全尺寸測試中真正對應的組合，而非只比水壓。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Retain offset direction at rotated and branched interfaces and select the matching full-size test combination, not pressure alone. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":23},{"id":"b102-v14-12","title":"接頭壓縮與水密包絡：失效診斷","titleEn":"Joint compression and sealing envelope: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-11"],"objective":"從症狀倒推「止水壓縮餘量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Gasket compression reserve” and propose discriminating checks, corrective actions and prevention.","instruction":"不同方向錯台可能讓密封接觸區遷移，單一正向試驗合格不能證明反向循環後仍水密。扭曲或沾污的止水條可形成旁通通道，即使平均縫寬合格仍可能漏水；盲目灌漿也可能只轉移出水位置。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Opposite offsets can shift the sealing contact zone; passing one-direction tests does not prove tightness after reversed cycles. A twisted or contaminated gasket creates bypass leakage despite acceptable mean width; indiscriminate grouting may merely move the outlet. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：平均壓縮量不能掩蓋局部脫離；全尺寸試驗的結果只對測試過的幾何、水壓及荷載歷程有效，幾何餘量本身並不是接觸壓力。","observationEn":"Link to the mechanism: Full-size test results apply only to their tested geometry, head and load history, while a calculated geometric reserve is neither contact pressure nor evidence of watertightness.","failure":"誤判風險：若相信「接縫平均寬度合格就不必量測局部錯台及扭轉。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"An acceptable average joint width makes local offset and twist measurements unnecessary.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-12-k1","title":"失效模式","titleEn":"Failure mode","text":"不同方向錯台可能讓密封接觸區遷移，單一正向試驗合格不能證明反向循環後仍水密。扭曲或沾污的止水條可形成旁通通道，即使平均縫寬合格仍可能漏水；盲目灌漿也可能只轉移出水位置。","textEn":"Opposite offsets can shift the sealing contact zone; passing one-direction tests does not prove tightness after reversed cycles. A twisted or contaminated gasket creates bypass leakage despite acceptable mean width; indiscriminate grouting may merely move the outlet.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「接頭壓縮與水密包絡」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Joint compression and sealing envelope\" shows distress, which diagnosis is most reasonable?","options":["不同方向錯台可能讓密封接觸區遷移，單一正向試驗合格不能證明反向循環後仍水密。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","增加工作面就可以直接把各面的理論產量相加。"],"optionsEn":["Opposite offsets can shift the sealing contact zone; passing one-direction tests does not prove tightness after reversed cycles.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Adding headings allows their theoretical outputs to be summed directly."],"answer":0,"explanation":"不同方向錯台可能讓密封接觸區遷移，單一正向試驗合格不能證明反向循環後仍水密。 需以量測區分可能原因。","explanationEn":"Opposite offsets can shift the sealing contact zone; passing one-direction tests does not prove tightness after reversed cycles. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":24},{"id":"b102-v14-13","title":"共享通道與運輸瓶頸：機制與系統路徑","titleEn":"Shared access and transport bottlenecks: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-12"],"objective":"說明「出渣運輸節拍」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Muck-transport cycle” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"長海底隧道的維修物流需在列車服務與服務通道使用間協調，備料的距離和返回時間會影響實際工作窗口，不只看工具進入時間。多工作面只有在供電、通風、出渣與材料供應同步充足時才增加總產量。共用豎井或軌道形成串聯瓶頸，排隊和維修窗口會降低名目容量；緩衝區太大又可能侵占通行與救援空間，因此不能單純把各面產能相加。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「出渣運輸節拍」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Maintenance logistics must fit railway service and service-access use; material distance and return time constrain the window beyond the time needed to bring tools inside. Multiple headings increase output only when power, air, muck transport and materials support them together. Shared shafts or railways become serial bottlenecks, while queues and maintenance reduce nominal capacity. Large buffers may obstruct personnel and rescue access, so face capacities cannot simply be added without a network-level transport and storage check. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Muck-transport cycle” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：車輛數=4 個；每車載量=21 t；往返週期=33 min。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: vehicles=4 count; payload=21 t; cycle=33 min.","failure":"常見誤解：「增加工作面就可以直接把各面的理論產量相加。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Adding headings allows their theoretical outputs to be summed directly.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「出渣運輸節拍」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Muck-transport cycle”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-13-k1","title":"共享通道與運輸瓶頸","titleEn":"Shared access and transport bottlenecks","text":"長海底隧道的維修物流需在列車服務與服務通道使用間協調，備料的距離和返回時間會影響實際工作窗口，不只看工具進入時間。多工作面只有在供電、通風、出渣與材料供應同步充足時才增加總產量。","textEn":"Maintenance logistics must fit railway service and service-access use; material distance and return time constrain the window beyond the time needed to bring tools inside. Multiple headings increase output only when power, air, muck transport and materials support them together.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：增加工作面就可以直接把各面的理論產量相加。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Adding headings allows their theoretical outputs to be summed directly. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「共享通道與運輸瓶頸」，下列哪一項敘述正確？","questionEn":"Which statement about \"Shared access and transport bottlenecks\" is correct?","options":["增加工作面就可以直接把各面的理論產量相加。","長海底隧道的維修物流需在列車服務與服務通道使用間協調，備料的距離和返回時間會影響實際工作窗口，不只看工具進入時間。","只要體積風量相同，不同海拔的空氣散熱量一定相同。"],"optionsEn":["Adding headings allows their theoretical outputs to be summed directly.","Maintenance logistics must fit railway service and service-access use.","Equal volumetric airflow provides identical cooling at every altitude."],"answer":1,"explanation":"長海底隧道的維修物流需在列車服務與服務通道使用間協調，備料的距離和返回時間會影響實際工作窗口，不只看工具進入時間。 其餘選項是常見誤解。","explanationEn":"Maintenance logistics must fit railway service and service-access use; material distance and return time constrain the window beyond the time needed to bring tools inside. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":25},{"id":"b102-v14-14","title":"共享通道與運輸瓶頸：定量估算","titleEn":"Shared access and transport bottlenecks: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-13"],"objective":"以數值模型估算「出渣運輸節拍」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Muck-transport cycle” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：車輛數=4 個；每車載量=21 t；往返週期=33 min。C=N payload 60/T=152.727 t/h。僅把往返週期增加10%，其他條件不變，重算為138.843 t/h。邊界：無排隊理想循環，並非共享路段實際產能；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: vehicles=4 count; payload=21 t; cycle=33 min. C=N payload 60/T=152.727 t/h. Increasing only cycle by 10% with all other inputs fixed gives 138.843 t/h. Boundary: Ideal cycle without queues, not actual shared-route production. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用工單時間戳分開進入、作業、清點及撤出，核對共用路線是否在同一窗口被另一任務占用。","observationEn":"How to cross-check: Separate access, work, inventory checks and withdrawal in work-order timestamps and identify overlapping use of shared routes.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：車輛數=4 個；每車載量=21 t；往返週期=33 min。C=N payload 60/T=152.727 t/h。僅把往返週期增加10%，其他條件不變，重算為138.843 t/h。邊界：無排隊理想循環，並非共享路段實際產能；不是本工程實測或允收值。","textEn":"Original teaching assumptions: vehicles=4 count; payload=21 t; cycle=33 min. C=N payload 60/T=152.727 t/h. Increasing only cycle by 10% with all other inputs fixed gives 138.843 t/h. Boundary: Ideal cycle without queues, not actual shared-route production. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「共享通道與運輸瓶頸」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Shared access and transport bottlenecks\", which statement holds?","options":["只要出口距離短，就不需要比較可用與所需安全時間。","設備有兩台就可以直接把各自故障率相乘判定安全。","原創教學假設：車輛數=4 個；每車載量=21 t；往返週期=33 min。"],"optionsEn":["Short exit distance removes the need to compare available and required safe time.","Two units allow their failure probabilities to be multiplied directly to establish safety.","Original teaching assumptions: vehicles=4 count; payload=21 t; cycle=33 min."],"answer":2,"explanation":"原創教學假設：車輛數=4 個；每車載量=21 t；往返週期=33 min。 重算時請保留單位。","explanationEn":"Original teaching assumptions: vehicles=4 count; payload=21 t; cycle=33 min. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":26},{"id":"b102-v14-15","title":"共享通道與運輸瓶頸：試驗與驗證","titleEn":"Shared access and transport bottlenecks: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「出渣運輸節拍」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Muck-transport cycle” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用工單時間戳分開進入、作業、清點及撤出，核對共用路線是否在同一窗口被另一任務占用。以裝載質量、往返時間及排隊時間重建物流曲線，再核對緩衝占用、共用通道優先權與維修時段。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Separate access, work, inventory checks and withdrawal in work-order timestamps and identify overlapping use of shared routes. Reconstruct flow from payload, round-trip and queue times, then check buffer occupancy, shared-route priorities and maintenance periods. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「出渣運輸節拍」的交付需回答：用工單時間戳分開進入、作業、清點及撤出，核對共用路線是否在同一窗口被另一任務占用。每日排程同時標示人員、材料和維修的占用時段，任何物流改線先檢查通風與應變通道，不能只看運量提升。","observationEn":"Site practice: For Channel Tunnel, the muck-transport cycle handover must address the following evidence: Separate access, work, inventory checks and withdrawal in work-order timestamps and identify overlapping use of shared routes. Schedules show personnel, materials and maintenance occupancy together; rerouting first checks ventilation and emergency access rather than only throughput gains.","failure":"注意干擾：只安排作業時間而不留撤出驗證，會把未清空的工作面錯報成可恢復列車服務。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Scheduling work without verified withdrawal time can incorrectly report an occupied worksite as ready for railway service. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-15-k1","title":"驗證方法","titleEn":"Verification method","text":"用工單時間戳分開進入、作業、清點及撤出，核對共用路線是否在同一窗口被另一任務占用。以裝載質量、往返時間及排隊時間重建物流曲線，再核對緩衝占用、共用通道優先權與維修時段。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Separate access, work, inventory checks and withdrawal in work-order timestamps and identify overlapping use of shared routes. Reconstruct flow from payload, round-trip and queue times, then check buffer occupancy, shared-route priorities and maintenance periods. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-15-k2","title":"現場實務","titleEn":"Site practice","text":"本案「出渣運輸節拍」的交付需回答：用工單時間戳分開進入、作業、清點及撤出，核對共用路線是否在同一窗口被另一任務占用。每日排程同時標示人員、材料和維修的占用時段，任何物流改線先檢查通風與應變通道，不能只看運量提升。","textEn":"For Channel Tunnel, the muck-transport cycle handover must address the following evidence: Separate access, work, inventory checks and withdrawal in work-order timestamps and identify overlapping use of shared routes. Schedules show personnel, materials and maintenance occupancy together; rerouting first checks ventilation and emergency access rather than only throughput gains.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「共享通道與運輸瓶頸」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Shared access and transport bottlenecks\"?","options":["用工單時間戳分開進入、作業、清點及撤出，核對共用路線是否在同一窗口被另一任務占用。","不確定度太難估計，報告中只寫最佳值即可。","目前沒有可見漏水就能在設計中忽略外水壓。"],"optionsEn":["Separate access, work, inventory checks and withdrawal in work-order timestamps and identify overlapping use of shared routes.","Uncertainty is too hard to estimate, so the report may state only the best value.","No visible leakage means that external water pressure can be omitted from design."],"answer":0,"explanation":"用工單時間戳分開進入、作業、清點及撤出，核對共用路線是否在同一窗口被另一任務占用。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Separate access, work, inventory checks and withdrawal in work-order timestamps and identify overlapping use of shared routes. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":27},{"id":"b102-v14-16","title":"共享通道與運輸瓶頸：失效診斷","titleEn":"Shared access and transport bottlenecks: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-15"],"objective":"從症狀倒推「出渣運輸節拍」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Muck-transport cycle” and propose discriminating checks, corrective actions and prevention.","instruction":"只安排作業時間而不留撤出驗證，會把未清空的工作面錯報成可恢復列車服務。把理想往返時間當全天常數會忽略交會等待與卸料堵塞，導致工作面停工或把材料堆入必要通道。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Scheduling work without verified withdrawal time can incorrectly report an occupied worksite as ready for railway service. Treating an ideal cycle as constant all day misses passing delays and unloading blockages, stopping headings or pushing material into essential access space. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：共用豎井或軌道形成串聯瓶頸，排隊和維修窗口會降低名目容量；緩衝區太大又可能侵占通行與救援空間，因此不能單純把各面產能相加。","observationEn":"Link to the mechanism: Large buffers may obstruct personnel and rescue access, so face capacities cannot simply be added without a network-level transport and storage check.","failure":"誤判風險：若相信「增加工作面就可以直接把各面的理論產量相加。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Adding headings allows their theoretical outputs to be summed directly.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-16-k1","title":"失效模式","titleEn":"Failure mode","text":"只安排作業時間而不留撤出驗證，會把未清空的工作面錯報成可恢復列車服務。把理想往返時間當全天常數會忽略交會等待與卸料堵塞，導致工作面停工或把材料堆入必要通道。","textEn":"Scheduling work without verified withdrawal time can incorrectly report an occupied worksite as ready for railway service. Treating an ideal cycle as constant all day misses passing delays and unloading blockages, stopping headings or pushing material into essential access space.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「共享通道與運輸瓶頸」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Shared access and transport bottlenecks\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","只安排作業時間而不留撤出驗證，會把未清空的工作面錯報成可恢復列車服務。","只要體積風量相同，不同海拔的空氣散熱量一定相同。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Scheduling work without verified withdrawal time can incorrectly report an occupied worksite as ready for railway service.","Equal volumetric airflow provides identical cooling at every altitude."],"answer":1,"explanation":"只安排作業時間而不留撤出驗證，會把未清空的工作面錯報成可恢復列車服務。 需以量測區分可能原因。","explanationEn":"Scheduling work without verified withdrawal time can incorrectly report an occupied worksite as ready for railway service. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":28}],"order":5},{"id":"b102-v14-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「熱源分配與空氣顯熱」與「列車壓力波與動壓量級」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Heat sources and sensible-air removal\" and \"Train pressure waves and dynamic-pressure scale\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b102-v14-17","title":"熱源分配與空氣顯熱：機制與系統路徑","titleEn":"Heat sources and sensible-air removal: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-16"],"objective":"說明「通風顯熱量」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Ventilation sensible heat” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"英法列車與設備熱源會隨服務密度改變，分析正常高峰和一條冷卻路徑維修時的空氣及水側熱帳，避免把裝置容量直接視為可移除熱量。深部岩體、列車和機械會向空氣持續放熱，空氣帶走的顯熱由質量流量與溫升決定。相同體積風量在不同密度下不具有相同散熱能力；濕度、岩體瞬變及水冷系統還需分開記帳，單一穩態熱平衡不能預測全部溫度尖峰。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「通風顯熱量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Traffic-dependent heat must be reconciled across air and water during peaks and cooling-path maintenance rather than equating installed capacity with removable heat. Deep rock, trains and machinery release heat to the air, whose sensible removal depends on mass flow and temperature rise. Equal volumetric flow at different density does not provide equal cooling. Moisture, transient rock heat and water cooling need separate accounts; a steady balance cannot predict every temperature peak or local worker exposure. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Ventilation sensible heat” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：空氣密度=1.2 kg/m³；體積風量=82 m³/s；定壓比熱=1.005 kJ/(kg·K)；溫升=12 K。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: air density=1.2 kg/m³; volume flow=82 m³/s; specific heat=1.005 kJ/(kg·K); temperature rise=12 K.","failure":"常見誤解：「只要體積風量相同，不同海拔的空氣散熱量一定相同。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal volumetric airflow provides identical cooling at every altitude.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「通風顯熱量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Ventilation sensible heat”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-17-k1","title":"熱源分配與空氣顯熱","titleEn":"Heat sources and sensible-air removal","text":"英法列車與設備熱源會隨服務密度改變，分析正常高峰和一條冷卻路徑維修時的空氣及水側熱帳，避免把裝置容量直接視為可移除熱量。深部岩體、列車和機械會向空氣持續放熱，空氣帶走的顯熱由質量流量與溫升決定。","textEn":"Traffic-dependent heat must be reconciled across air and water during peaks and cooling-path maintenance rather than equating installed capacity with removable heat. Deep rock, trains and machinery release heat to the air, whose sensible removal depends on mass flow and temperature rise.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要體積風量相同，不同海拔的空氣散熱量一定相同。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal volumetric airflow provides identical cooling at every altitude. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「熱源分配與空氣顯熱」，下列哪一項敘述正確？","questionEn":"Which statement about \"Heat sources and sensible-air removal\" is correct?","options":["只要體積風量相同，不同海拔的空氣散熱量一定相同。","動壓公式算出的數值就是長鐵路隧道完整壓力波。","英法列車與設備熱源會隨服務密度改變，分析正常高峰和一條冷卻路徑維修時的空氣及水側熱帳，避免把裝置容量直接視為可移除熱量。"],"optionsEn":["Equal volumetric airflow provides identical cooling at every altitude.","A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.","Traffic-dependent heat must be reconciled across air and water during peaks and cooling-path maintenance rather than equating installed capacity with removable heat."],"answer":2,"explanation":"英法列車與設備熱源會隨服務密度改變，分析正常高峰和一條冷卻路徑維修時的空氣及水側熱帳，避免把裝置容量直接視為可移除熱量。 其餘選項是常見誤解。","explanationEn":"Traffic-dependent heat must be reconciled across air and water during peaks and cooling-path maintenance rather than equating installed capacity with removable heat. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":29},{"id":"b102-v14-18","title":"熱源分配與空氣顯熱：定量估算","titleEn":"Heat sources and sensible-air removal: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-17"],"objective":"以數值模型估算「通風顯熱量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Ventilation sensible heat” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：空氣密度=1.2 kg/m³；體積風量=82 m³/s；定壓比熱=1.005 kJ/(kg·K)；溫升=12 K。Q=ρVcpΔT=1186.7 kW。僅把體積風量增加10%，其他條件不變，重算為1305.37 kW。邊界：僅空氣顯熱，不含濕度潛熱及岩體瞬變；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: air density=1.2 kg/m³; volume flow=82 m³/s; specific heat=1.005 kJ/(kg·K); temperature rise=12 K. Q=ρVcpΔT=1186.7 kW. Increasing only volume flow by 10% with all other inputs fixed gives 1305.37 kW. Boundary: Sensible air heat only, excluding latent heat and rock transients. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：配對列車通過時段、設備功率、進出口溫差和流量，檢查熱量殘差是否集中在服務高峰。","observationEn":"How to cross-check: Pair train passages, equipment power, temperature rise and flow, checking whether energy residuals cluster during peak service.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：空氣密度=1.2 kg/m³；體積風量=82 m³/s；定壓比熱=1.005 kJ/(kg·K)；溫升=12 K。Q=ρVcpΔT=1186.7 kW。僅把體積風量增加10%，其他條件不變，重算為1305.37 kW。邊界：僅空氣顯熱，不含濕度潛熱及岩體瞬變；不是本工程實測或允收值。","textEn":"Original teaching assumptions: air density=1.2 kg/m³; volume flow=82 m³/s; specific heat=1.005 kJ/(kg·K); temperature rise=12 K. Q=ρVcpΔT=1186.7 kW. Increasing only volume flow by 10% with all other inputs fixed gives 1305.37 kW. Boundary: Sensible air heat only, excluding latent heat and rock transients. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「熱源分配與空氣顯熱」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Heat sources and sensible-air removal\", which statement holds?","options":["原創教學假設：空氣密度=1.2 kg/m³；體積風量=82 m³/s；定壓比熱=1.005 kJ/(kg·K)；溫升=12 K。","集水坑總容積除以平均入流就是保證可用的反應時間。","全部檔案上傳完成就代表工程交接已經驗收合格。"],"optionsEn":["Original teaching assumptions: air density=1.2 kg/m³; volume flow=82 m³/s; specific heat=1.005 kJ/(kg·K); temperature rise=12 K.","Gross sump volume divided by average inflow is a guaranteed response time.","Uploading all files means that engineering handover has been accepted."],"answer":0,"explanation":"原創教學假設：空氣密度=1.2 kg/m³；體積風量=82 m³/s；定壓比熱=1.005 kJ/(kg·K)；溫升=12 K。 重算時請保留單位。","explanationEn":"Original teaching assumptions: air density=1.2 kg/m³; volume flow=82 m³/s; specific heat=1.005 kJ/(kg·K); temperature rise=12 K. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":30},{"id":"b102-v14-19","title":"熱源分配與空氣顯熱：試驗與驗證","titleEn":"Heat sources and sensible-air removal: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「通風顯熱量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Ventilation sensible heat” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"配對列車通過時段、設備功率、進出口溫差和流量，檢查熱量殘差是否集中在服務高峰。同步量測進出口溫濕度、風量及設備負載，分開平均與尖峰時段，用能量收支殘差檢查漏列熱源。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Pair train passages, equipment power, temperature rise and flow, checking whether energy residuals cluster during peak service. Synchronise inlet/outlet temperature, humidity, flow and equipment load, separate average and peak periods, and use energy residuals to identify missing sources. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「通風顯熱量」的交付需回答：配對列車通過時段、設備功率、進出口溫差和流量，檢查熱量殘差是否集中在服務高峰。熱帳分別列岩體、交通、機械與水冷路徑，交接時保存季節和負載範圍，設備增設前須重新核對可用散熱能力。","observationEn":"Site practice: For Channel Tunnel, the ventilation sensible heat handover must address the following evidence: Pair train passages, equipment power, temperature rise and flow, checking whether energy residuals cluster during peak service. Keep rock, traffic, machinery and water-cooling paths separate; retain seasonal and load ranges and reassess cooling capacity before adding equipment.","failure":"注意干擾：平均日溫度正常可能遮住列車連續通過的局部熱峰，需保留時間解析度再判斷冷卻不足。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A normal daily mean can conceal local peaks during successive train passages; retain time resolution before judging cooling adequacy. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-19-k1","title":"驗證方法","titleEn":"Verification method","text":"配對列車通過時段、設備功率、進出口溫差和流量，檢查熱量殘差是否集中在服務高峰。同步量測進出口溫濕度、風量及設備負載，分開平均與尖峰時段，用能量收支殘差檢查漏列熱源。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Pair train passages, equipment power, temperature rise and flow, checking whether energy residuals cluster during peak service. Synchronise inlet/outlet temperature, humidity, flow and equipment load, separate average and peak periods, and use energy residuals to identify missing sources. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-19-k2","title":"現場實務","titleEn":"Site practice","text":"本案「通風顯熱量」的交付需回答：配對列車通過時段、設備功率、進出口溫差和流量，檢查熱量殘差是否集中在服務高峰。熱帳分別列岩體、交通、機械與水冷路徑，交接時保存季節和負載範圍，設備增設前須重新核對可用散熱能力。","textEn":"For Channel Tunnel, the ventilation sensible heat handover must address the following evidence: Pair train passages, equipment power, temperature rise and flow, checking whether energy residuals cluster during peak service. Keep rock, traffic, machinery and water-cooling paths separate; retain seasonal and load ranges and reassess cooling capacity before adding equipment.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「熱源分配與空氣顯熱」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Heat sources and sensible-air removal\"?","options":["允收準則可以等看到量測數據後再決定。","配對列車通過時段、設備功率、進出口溫差和流量，檢查熱量殘差是否集中在服務高峰。","混凝土強度達標就不必檢查接縫轉動與偏壓。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Pair train passages, equipment power, temperature rise and flow, checking whether energy residuals cluster during peak service.","Passing concrete strength eliminates the need to check joint rotation and uneven pressure."],"answer":1,"explanation":"配對列車通過時段、設備功率、進出口溫差和流量，檢查熱量殘差是否集中在服務高峰。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Pair train passages, equipment power, temperature rise and flow, checking whether energy residuals cluster during peak service. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":31},{"id":"b102-v14-20","title":"熱源分配與空氣顯熱：失效診斷","titleEn":"Heat sources and sensible-air removal: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-19"],"objective":"從症狀倒推「通風顯熱量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Ventilation sensible heat” and propose discriminating checks, corrective actions and prevention.","instruction":"平均日溫度正常可能遮住列車連續通過的局部熱峰，需保留時間解析度再判斷冷卻不足。把低密度空氣視為海平面空氣會高估散熱，局部熱點也可能被斷面平均溫度掩蓋，導致設備或工作環境超限。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A normal daily mean can conceal local peaks during successive train passages; retain time resolution before judging cooling adequacy. Assuming sea-level density overstates cooling at low density, while cross-sectional averages hide hot spots affecting equipment and the work environment. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：相同體積風量在不同密度下不具有相同散熱能力；濕度、岩體瞬變及水冷系統還需分開記帳，單一穩態熱平衡不能預測全部溫度尖峰。","observationEn":"Link to the mechanism: Moisture, transient rock heat and water cooling need separate accounts; a steady balance cannot predict every temperature peak or local worker exposure.","failure":"誤判風險：若相信「只要體積風量相同，不同海拔的空氣散熱量一定相同。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal volumetric airflow provides identical cooling at every altitude.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-20-k1","title":"失效模式","titleEn":"Failure mode","text":"平均日溫度正常可能遮住列車連續通過的局部熱峰，需保留時間解析度再判斷冷卻不足。把低密度空氣視為海平面空氣會高估散熱，局部熱點也可能被斷面平均溫度掩蓋，導致設備或工作環境超限。","textEn":"A normal daily mean can conceal local peaks during successive train passages; retain time resolution before judging cooling adequacy. Assuming sea-level density overstates cooling at low density, while cross-sectional averages hide hot spots affecting equipment and the work environment.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「熱源分配與空氣顯熱」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Heat sources and sensible-air removal\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","動壓公式算出的數值就是長鐵路隧道完整壓力波。","平均日溫度正常可能遮住列車連續通過的局部熱峰，需保留時間解析度再判斷冷卻不足。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.","A normal daily mean can conceal local peaks during successive train passages; retain time resolution before judging cooling adequacy."],"answer":2,"explanation":"平均日溫度正常可能遮住列車連續通過的局部熱峰，需保留時間解析度再判斷冷卻不足。 需以量測區分可能原因。","explanationEn":"A normal daily mean can conceal local peaks during successive train passages; retain time resolution before judging cooling adequacy. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":32},{"id":"b102-v14-21","title":"列車壓力波與動壓量級：機制與系統路徑","titleEn":"Train pressure waves and dynamic-pressure scale: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-20"],"objective":"說明「入口壓力擾動」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Portal pressure disturbance” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"英法主孔的列車種類與速度不同，阻塞比和交會情境應分案；服務通道門位又會改變壓力反射邊界，不能用單一動壓替代波動歷程。列車進洞壓縮前方空氣，波動在洞口、橫通道和斷面變化處傳播與反射。速度和阻塞比影響壓力量級，但不可壓動壓只是比較尺度，不能替代可壓縮瞬變計算；兩車交會、門位與列車外形都可能改變乘客及設備的壓力歷程。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「入口壓力擾動」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Different train types, speeds and encounter cases change blockage and wave behaviour; service-access door states also alter reflections beyond a single dynamic-pressure estimate. A train entering a tunnel compresses the air ahead, producing waves reflected at portals, passages and section changes. Speed and blockage influence magnitude, but incompressible dynamic pressure is only a comparison scale, not a compressible transient solution. Train encounters, door states and vehicle shape change the pressure histories experienced by passengers and equipment. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Portal pressure disturbance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：空氣密度=1.2 kg/m³；列車速度=41 m/s。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: air density=1.2 kg/m³; train speed=41 m/s. q=ρv²/2=1008.6 Pa.","failure":"常見誤解：「動壓公式算出的數值就是長鐵路隧道完整壓力波。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「入口壓力擾動」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Portal pressure disturbance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-21-k1","title":"列車壓力波與動壓量級","titleEn":"Train pressure waves and dynamic-pressure scale","text":"英法主孔的列車種類與速度不同，阻塞比和交會情境應分案；服務通道門位又會改變壓力反射邊界，不能用單一動壓替代波動歷程。列車進洞壓縮前方空氣，波動在洞口、橫通道和斷面變化處傳播與反射。","textEn":"Different train types, speeds and encounter cases change blockage and wave behaviour; service-access door states also alter reflections beyond a single dynamic-pressure estimate. A train entering a tunnel compresses the air ahead, producing waves reflected at portals, passages and section changes.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：動壓公式算出的數值就是長鐵路隧道完整壓力波。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「列車壓力波與動壓量級」，下列哪一項敘述正確？","questionEn":"Which statement about \"Train pressure waves and dynamic-pressure scale\" is correct?","options":["英法主孔的列車種類與速度不同，阻塞比和交會情境應分案；服務通道門位又會改變壓力反射邊界，不能用單一動壓替代波動歷程。","動壓公式算出的數值就是長鐵路隧道完整壓力波。","只要出口距離短，就不需要比較可用與所需安全時間。"],"optionsEn":["Different train types, speeds and encounter cases change blockage and wave behaviour.","A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.","Short exit distance removes the need to compare available and required safe time."],"answer":0,"explanation":"英法主孔的列車種類與速度不同，阻塞比和交會情境應分案；服務通道門位又會改變壓力反射邊界，不能用單一動壓替代波動歷程。 其餘選項是常見誤解。","explanationEn":"Different train types, speeds and encounter cases change blockage and wave behaviour; service-access door states also alter reflections beyond a single dynamic-pressure estimate. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":33},{"id":"b102-v14-22","title":"列車壓力波與動壓量級：定量估算","titleEn":"Train pressure waves and dynamic-pressure scale: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-21"],"objective":"以數值模型估算「入口壓力擾動」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Portal pressure disturbance” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：空氣密度=1.2 kg/m³；列車速度=41 m/s。q=ρv²/2=1008.6 Pa。僅把列車速度增加10%，其他條件不變，重算為1220.41 Pa。邊界：不可壓動壓尺度，不是可壓縮列車壓力波解；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: air density=1.2 kg/m³; train speed=41 m/s. q=ρv²/2=1008.6 Pa. Increasing only train speed by 10% with all other inputs fixed gives 1220.41 Pa. Boundary: Incompressible dynamic-pressure scale, not a compressible train pressure-wave solution. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在列車通過前後同步量測門兩側壓力，將列車編組與門位一起保存，檢查反射峰抵達時間。","observationEn":"How to cross-check: Synchronise pressure across doors before and after passage, retaining formation and door state to check reflected-wave arrival.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：空氣密度=1.2 kg/m³；列車速度=41 m/s。q=ρv²/2=1008.6 Pa。僅把列車速度增加10%，其他條件不變，重算為1220.41 Pa。邊界：不可壓動壓尺度，不是可壓縮列車壓力波解；不是本工程實測或允收值。","textEn":"Original teaching assumptions: air density=1.2 kg/m³; train speed=41 m/s. q=ρv²/2=1008.6 Pa. Increasing only train speed by 10% with all other inputs fixed gives 1220.41 Pa. Boundary: Incompressible dynamic-pressure scale, not a compressible train pressure-wave solution. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「列車壓力波與動壓量級」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Train pressure waves and dynamic-pressure scale\", which statement holds?","options":["設備有兩台就可以直接把各自故障率相乘判定安全。","原創教學假設：空氣密度=1.2 kg/m³；列車速度=41 m/s。","目前沒有可見漏水就能在設計中忽略外水壓。"],"optionsEn":["Two units allow their failure probabilities to be multiplied directly to establish safety.","Original teaching assumptions: air density=1.2 kg/m³; train speed=41 m/s. q=ρv²/2=1008.6 Pa.","No visible leakage means that external water pressure can be omitted from design."],"answer":1,"explanation":"原創教學假設：空氣密度=1.2 kg/m³；列車速度=41 m/s。 重算時請保留單位。","explanationEn":"Original teaching assumptions: air density=1.2 kg/m³; train speed=41 m/s. q=ρv²/2=1008.6 Pa. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":34},{"id":"b102-v14-23","title":"列車壓力波與動壓量級：試驗與驗證","titleEn":"Train pressure waves and dynamic-pressure scale: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「入口壓力擾動」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Portal pressure disturbance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在列車通過前後同步量測門兩側壓力，將列車編組與門位一起保存，檢查反射峰抵達時間。以相同列車編組、速度和門位量測多點壓力歷程，檢查峰值、上升時間及反射抵達時刻，而不只比較一個最大值。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Synchronise pressure across doors before and after passage, retaining formation and door state to check reflected-wave arrival. Measure pressure histories at several points with matching train formation, speed and door states, comparing rise time and reflection arrival as well as peaks. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「入口壓力擾動」的交付需回答：在列車通過前後同步量測門兩側壓力，將列車編組與門位一起保存，檢查反射峰抵達時間。試車報告記錄編組、速度、溫度及門位版本，土建斷面變更與設備耐壓驗證共用同一氣動模型，不能各自選有利情境。","observationEn":"Site practice: For Channel Tunnel, the portal pressure disturbance handover must address the following evidence: Synchronise pressure across doors before and after passage, retaining formation and door state to check reflected-wave arrival. Trial reports retain formation, speed, temperature and door revisions; civil changes and equipment-pressure checks share one aerodynamic model rather than selectively favourable cases.","failure":"注意干擾：只存最大壓力不存升壓時間，可能漏掉設備密封與乘客感受所受的快速變化。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Saving only peak pressure loses rapid changes relevant to seals and passenger comfort. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-23-k1","title":"驗證方法","titleEn":"Verification method","text":"在列車通過前後同步量測門兩側壓力，將列車編組與門位一起保存，檢查反射峰抵達時間。以相同列車編組、速度和門位量測多點壓力歷程，檢查峰值、上升時間及反射抵達時刻，而不只比較一個最大值。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Synchronise pressure across doors before and after passage, retaining formation and door state to check reflected-wave arrival. Measure pressure histories at several points with matching train formation, speed and door states, comparing rise time and reflection arrival as well as peaks. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-23-k2","title":"現場實務","titleEn":"Site practice","text":"本案「入口壓力擾動」的交付需回答：在列車通過前後同步量測門兩側壓力，將列車編組與門位一起保存，檢查反射峰抵達時間。試車報告記錄編組、速度、溫度及門位版本，土建斷面變更與設備耐壓驗證共用同一氣動模型，不能各自選有利情境。","textEn":"For Channel Tunnel, the portal pressure disturbance handover must address the following evidence: Synchronise pressure across doors before and after passage, retaining formation and door state to check reflected-wave arrival. Trial reports retain formation, speed, temperature and door revisions; civil changes and equipment-pressure checks share one aerodynamic model rather than selectively favourable cases.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「列車壓力波與動壓量級」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Train pressure waves and dynamic-pressure scale\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","接縫平均寬度合格就不必量測局部錯台及扭轉。","在列車通過前後同步量測門兩側壓力，將列車編組與門位一起保存，檢查反射峰抵達時間。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","An acceptable average joint width makes local offset and twist measurements unnecessary.","Synchronise pressure across doors before and after passage, retaining formation and door state to check reflected-wave arrival."],"answer":2,"explanation":"在列車通過前後同步量測門兩側壓力，將列車編組與門位一起保存，檢查反射峰抵達時間。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Synchronise pressure across doors before and after passage, retaining formation and door state to check reflected-wave arrival. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":35},{"id":"b102-v14-24","title":"列車壓力波與動壓量級：失效診斷","titleEn":"Train pressure waves and dynamic-pressure scale: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-23"],"objective":"從症狀倒推「入口壓力擾動」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Portal pressure disturbance” and propose discriminating checks, corrective actions and prevention.","instruction":"只存最大壓力不存升壓時間，可能漏掉設備密封與乘客感受所受的快速變化。以單一動壓數字當允收值會漏掉壓力梯度與反射疊加，可能使門扇、密封或乘客舒適度需求被低估。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Saving only peak pressure loses rapid changes relevant to seals and passenger comfort. Using one dynamic-pressure value for acceptance misses gradients and superposed reflections, understating demands on doors, seals or passenger comfort. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：速度和阻塞比影響壓力量級，但不可壓動壓只是比較尺度，不能替代可壓縮瞬變計算；兩車交會、門位與列車外形都可能改變乘客及設備的壓力歷程。","observationEn":"Link to the mechanism: Train encounters, door states and vehicle shape change the pressure histories experienced by passengers and equipment.","failure":"誤判風險：若相信「動壓公式算出的數值就是長鐵路隧道完整壓力波。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-24-k1","title":"失效模式","titleEn":"Failure mode","text":"只存最大壓力不存升壓時間，可能漏掉設備密封與乘客感受所受的快速變化。以單一動壓數字當允收值會漏掉壓力梯度與反射疊加，可能使門扇、密封或乘客舒適度需求被低估。","textEn":"Saving only peak pressure loses rapid changes relevant to seals and passenger comfort. Using one dynamic-pressure value for acceptance misses gradients and superposed reflections, understating demands on doors, seals or passenger comfort.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「列車壓力波與動壓量級」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Train pressure waves and dynamic-pressure scale\" shows distress, which diagnosis is most reasonable?","options":["只存最大壓力不存升壓時間，可能漏掉設備密封與乘客感受所受的快速變化。","只要結構還沒倒，就代表安全餘裕仍然足夠。","只要出口距離短，就不需要比較可用與所需安全時間。"],"optionsEn":["Saving only peak pressure loses rapid changes relevant to seals and passenger comfort.","As long as the structure is still standing, its safety margin must still be adequate.","Short exit distance removes the need to compare available and required safe time."],"answer":0,"explanation":"只存最大壓力不存升壓時間，可能漏掉設備密封與乘客感受所受的快速變化。 需以量測區分可能原因。","explanationEn":"Saving only peak pressure loses rapid changes relevant to seals and passenger comfort. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":36}],"order":6},{"id":"b102-v14-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「疏散時間與分區可用性」與「停泵緩衝與有效集水容積」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Evacuation time and zone availability\" and \"Outage buffer and effective sump volume\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b102-v14-25","title":"疏散時間與分區可用性：機制與系統路徑","titleEn":"Evacuation time and zone availability: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-24"],"objective":"說明「所需疏散時間」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Required evacuation time” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"英法服務通道提供不同於運行孔的接收空間，疏散模型需確認到達之後的人流容量與可用狀態，不能在越過第一道門時就結束計時。疏散時間包含辨識、反應、移動及排隊，不只由出口距離決定。人員速度會受煙熱、能見度及行動能力影響，安全判斷還要比較可用安全時間；橫通道存在但門或鄰孔不可用時，圖上的最短路線不一定能作實際選擇。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「所需疏散時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Service access provides a receiving space distinct from the running bore; evacuation modelling must include capacity and availability after the first doorway, not stop its clock there. Evacuation includes detection, response, travel and queues, not merely distance to an exit. Smoke, visibility and mobility alter walking speed, while safety requires comparison with available safe time. A passage shown on a plan may be unusable because its door or receiving bore is unavailable, invalidating the nominal shortest route. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Required evacuation time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：前置時間=82 s；行走距離=320 m；行走速度=0.8 m/s。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: pre-movement time=82 s; travel distance=320 m; walking speed=0.8 m/s.","failure":"常見誤解：「只要出口距離短，就不需要比較可用與所需安全時間。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Short exit distance removes the need to compare available and required safe time.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「所需疏散時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Required evacuation time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-25-k1","title":"疏散時間與分區可用性","titleEn":"Evacuation time and zone availability","text":"英法服務通道提供不同於運行孔的接收空間，疏散模型需確認到達之後的人流容量與可用狀態，不能在越過第一道門時就結束計時。疏散時間包含辨識、反應、移動及排隊，不只由出口距離決定。","textEn":"Service access provides a receiving space distinct from the running bore; evacuation modelling must include capacity and availability after the first doorway, not stop its clock there. Evacuation includes detection, response, travel and queues, not merely distance to an exit.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要出口距離短，就不需要比較可用與所需安全時間。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Short exit distance removes the need to compare available and required safe time. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「疏散時間與分區可用性」，下列哪一項敘述正確？","questionEn":"Which statement about \"Evacuation time and zone availability\" is correct?","options":["只要出口距離短，就不需要比較可用與所需安全時間。","英法服務通道提供不同於運行孔的接收空間，疏散模型需確認到達之後的人流容量與可用狀態，不能在越過第一道門時就結束計時。","集水坑總容積除以平均入流就是保證可用的反應時間。"],"optionsEn":["Short exit distance removes the need to compare available and required safe time.","Service access provides a receiving space distinct from the running bore.","Gross sump volume divided by average inflow is a guaranteed response time."],"answer":1,"explanation":"英法服務通道提供不同於運行孔的接收空間，疏散模型需確認到達之後的人流容量與可用狀態，不能在越過第一道門時就結束計時。 其餘選項是常見誤解。","explanationEn":"Service access provides a receiving space distinct from the running bore; evacuation modelling must include capacity and availability after the first doorway, not stop its clock there. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":37},{"id":"b102-v14-26","title":"疏散時間與分區可用性：定量估算","titleEn":"Evacuation time and zone availability: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-25"],"objective":"以數值模型估算「所需疏散時間」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Required evacuation time” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：前置時間=82 s；行走距離=320 m；行走速度=0.8 m/s。RSET=tpre+d/v=482 s。僅把行走距離增加10%，其他條件不變，重算為522 s。邊界：單群體固定速度，不含排隊煙熱及能力差異，不能單獨判安全；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: pre-movement time=82 s; travel distance=320 m; walking speed=0.8 m/s. RSET=tpre+d/v=482 s. Increasing only travel distance by 10% with all other inputs fixed gives 522 s. Boundary: One group at fixed speed without queues, smoke or mobility differences; not a safety conclusion. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：演練或模擬分開通過橫通道門與後續移動時間，核對接收區人數及通訊延遲。","observationEn":"How to cross-check: Separate doorway crossing from onward movement in drills or models, checking receiving-zone occupancy and communication delays.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：前置時間=82 s；行走距離=320 m；行走速度=0.8 m/s。RSET=tpre+d/v=482 s。僅把行走距離增加10%，其他條件不變，重算為522 s。邊界：單群體固定速度，不含排隊煙熱及能力差異，不能單獨判安全；不是本工程實測或允收值。","textEn":"Original teaching assumptions: pre-movement time=82 s; travel distance=320 m; walking speed=0.8 m/s. RSET=tpre+d/v=482 s. Increasing only travel distance by 10% with all other inputs fixed gives 522 s. Boundary: One group at fixed speed without queues, smoke or mobility differences; not a safety conclusion. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「疏散時間與分區可用性」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Evacuation time and zone availability\", which statement holds?","options":["全部檔案上傳完成就代表工程交接已經驗收合格。","混凝土強度達標就不必檢查接縫轉動與偏壓。","原創教學假設：前置時間=82 s；行走距離=320 m；行走速度=0.8 m/s。"],"optionsEn":["Uploading all files means that engineering handover has been accepted.","Passing concrete strength eliminates the need to check joint rotation and uneven pressure.","Original teaching assumptions: pre-movement time=82 s; travel distance=320 m; walking speed=0.8 m/s."],"answer":2,"explanation":"原創教學假設：前置時間=82 s；行走距離=320 m；行走速度=0.8 m/s。 重算時請保留單位。","explanationEn":"Original teaching assumptions: pre-movement time=82 s; travel distance=320 m; walking speed=0.8 m/s. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":38},{"id":"b102-v14-27","title":"疏散時間與分區可用性：試驗與驗證","titleEn":"Evacuation time and zone availability: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「所需疏散時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Required evacuation time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"演練或模擬分開通過橫通道門與後續移動時間，核對接收區人數及通訊延遲。以人流模擬或受控演練分辨前置時間、行走與門口排隊，核對每個出口接收區的可用狀態及通訊紀錄。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Separate doorway crossing from onward movement in drills or models, checking receiving-zone occupancy and communication delays. Separate pre-movement, travel and doorway queues through simulation or controlled drills, checking receiving-zone availability and communication records for each exit. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「所需疏散時間」的交付需回答：演練或模擬分開通過橫通道門與後續移動時間，核對接收區人數及通訊延遲。疏散模型保留人口、速度分布及出口狀態，演練改動由營運與防災責任者批准，教材算例不得當作現場指揮程序。","observationEn":"Site practice: For Channel Tunnel, the required evacuation time handover must address the following evidence: Separate doorway crossing from onward movement in drills or models, checking receiving-zone occupancy and communication delays. Retain population, speed distribution and exit states; operations and fire-safety owners approve drill changes, and classroom calculations are not incident-command procedures.","failure":"注意干擾：通道本身可用但接收區壅塞時，隊列會回堵主孔，使用單一平均步速會低估所需時間。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Congestion in an otherwise accessible receiving zone can queue people back into the running bore and defeat an average-speed estimate. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-27-k1","title":"驗證方法","titleEn":"Verification method","text":"演練或模擬分開通過橫通道門與後續移動時間，核對接收區人數及通訊延遲。以人流模擬或受控演練分辨前置時間、行走與門口排隊，核對每個出口接收區的可用狀態及通訊紀錄。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Separate doorway crossing from onward movement in drills or models, checking receiving-zone occupancy and communication delays. Separate pre-movement, travel and doorway queues through simulation or controlled drills, checking receiving-zone availability and communication records for each exit. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-27-k2","title":"現場實務","titleEn":"Site practice","text":"本案「所需疏散時間」的交付需回答：演練或模擬分開通過橫通道門與後續移動時間，核對接收區人數及通訊延遲。疏散模型保留人口、速度分布及出口狀態，演練改動由營運與防災責任者批准，教材算例不得當作現場指揮程序。","textEn":"For Channel Tunnel, the required evacuation time handover must address the following evidence: Separate doorway crossing from onward movement in drills or models, checking receiving-zone occupancy and communication delays. Retain population, speed distribution and exit states; operations and fire-safety owners approve drill changes, and classroom calculations are not incident-command procedures.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「疏散時間與分區可用性」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Evacuation time and zone availability\"?","options":["演練或模擬分開通過橫通道門與後續移動時間，核對接收區人數及通訊延遲。","量測時不必記錄溫度、水頭、開挖序列與施工荷重，因為它們不會影響結果。","增加工作面就可以直接把各面的理論產量相加。"],"optionsEn":["Separate doorway crossing from onward movement in drills or models, checking receiving-zone occupancy and communication delays.","Temperature, water head, excavation sequence and construction loads need not be recorded because they cannot affect the result.","Adding headings allows their theoretical outputs to be summed directly."],"answer":0,"explanation":"演練或模擬分開通過橫通道門與後續移動時間，核對接收區人數及通訊延遲。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Separate doorway crossing from onward movement in drills or models, checking receiving-zone occupancy and communication delays. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":39},{"id":"b102-v14-28","title":"疏散時間與分區可用性：失效診斷","titleEn":"Evacuation time and zone availability: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-27"],"objective":"從症狀倒推「所需疏散時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Required evacuation time” and propose discriminating checks, corrective actions and prevention.","instruction":"通道本身可用但接收區壅塞時，隊列會回堵主孔，使用單一平均步速會低估所需時間。以最快成人速度套全部旅客會低估需求，若忽略接收孔受煙或車流影響，疏散可能移到另一個危險邊界。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Congestion in an otherwise accessible receiving zone can queue people back into the running bore and defeat an average-speed estimate. Applying the fastest adult speed to everyone understates demand; overlooking smoke or traffic in the receiving bore can transfer evacuees into another hazard. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：人員速度會受煙熱、能見度及行動能力影響，安全判斷還要比較可用安全時間；橫通道存在但門或鄰孔不可用時，圖上的最短路線不一定能作實際選擇。","observationEn":"Link to the mechanism: A passage shown on a plan may be unusable because its door or receiving bore is unavailable, invalidating the nominal shortest route.","failure":"誤判風險：若相信「只要出口距離短，就不需要比較可用與所需安全時間。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Short exit distance removes the need to compare available and required safe time.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-28-k1","title":"失效模式","titleEn":"Failure mode","text":"通道本身可用但接收區壅塞時，隊列會回堵主孔，使用單一平均步速會低估所需時間。以最快成人速度套全部旅客會低估需求，若忽略接收孔受煙或車流影響，疏散可能移到另一個危險邊界。","textEn":"Congestion in an otherwise accessible receiving zone can queue people back into the running bore and defeat an average-speed estimate. Applying the fastest adult speed to everyone understates demand; overlooking smoke or traffic in the receiving bore can transfer evacuees into another hazard.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「疏散時間與分區可用性」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Evacuation time and zone availability\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","通道本身可用但接收區壅塞時，隊列會回堵主孔，使用單一平均步速會低估所需時間。","集水坑總容積除以平均入流就是保證可用的反應時間。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Congestion in an otherwise accessible receiving zone can queue people back into the running bore and defeat an average-speed estimate.","Gross sump volume divided by average inflow is a guaranteed response time."],"answer":1,"explanation":"通道本身可用但接收區壅塞時，隊列會回堵主孔，使用單一平均步速會低估所需時間。 需以量測區分可能原因。","explanationEn":"Congestion in an otherwise accessible receiving zone can queue people back into the running bore and defeat an average-speed estimate. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":40},{"id":"b102-v14-29","title":"停泵緩衝與有效集水容積：機制與系統路徑","titleEn":"Outage buffer and effective sump volume: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-28"],"objective":"說明「剩餘集水容積」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Remaining sump volume” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"海底排水的可靠性需連結低點集水、供電與維修隔離，假想兩台泵中一台退出時，分析淨入流與警報延遲而不把原容量沿用。集水坑在泵停止後提供有限緩衝，剩餘容積需扣除初始水量、沉積及不可用死角。緩衝時間取決於淨入流，不是名牌抽水能力；警報延遲、備援切換與水量突增會消耗餘裕，排水電力又可能與其他安全設備共用失效原因。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「剩餘集水容積」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Link low-point sumps, power and maintenance isolation; when one hypothetical pump is unavailable, recalculate net inflow and alarm delay rather than retaining the original capacity. A sump offers finite buffering after pumps stop, with usable volume reduced by initial water, sediment and dead spaces. Buffer time depends on net inflow rather than pump nameplate capacity. Alarm delay, transfer time and inflow surges consume reserve, while shared electrical dependencies may disable drainage and other safety equipment together. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Remaining sump volume” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：有效剩餘容積=320 m³；淨入流=0.19 m³/s。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: usable reserve=320 m³; net inflow=0.19 m³/s. t=V/Q/60=28.0702 min.","failure":"常見誤解：「集水坑總容積除以平均入流就是保證可用的反應時間。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Gross sump volume divided by average inflow is a guaranteed response time.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「剩餘集水容積」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Remaining sump volume”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-29-k1","title":"停泵緩衝與有效集水容積","titleEn":"Outage buffer and effective sump volume","text":"海底排水的可靠性需連結低點集水、供電與維修隔離，假想兩台泵中一台退出時，分析淨入流與警報延遲而不把原容量沿用。集水坑在泵停止後提供有限緩衝，剩餘容積需扣除初始水量、沉積及不可用死角。","textEn":"Link low-point sumps, power and maintenance isolation; when one hypothetical pump is unavailable, recalculate net inflow and alarm delay rather than retaining the original capacity. A sump offers finite buffering after pumps stop, with usable volume reduced by initial water, sediment and dead spaces.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：集水坑總容積除以平均入流就是保證可用的反應時間。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Gross sump volume divided by average inflow is a guaranteed response time. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「停泵緩衝與有效集水容積」，下列哪一項敘述正確？","questionEn":"Which statement about \"Outage buffer and effective sump volume\" is correct?","options":["集水坑總容積除以平均入流就是保證可用的反應時間。","設備有兩台就可以直接把各自故障率相乘判定安全。","海底排水的可靠性需連結低點集水、供電與維修隔離，假想兩台泵中一台退出時，分析淨入流與警報延遲而不把原容量沿用。"],"optionsEn":["Gross sump volume divided by average inflow is a guaranteed response time.","Two units allow their failure probabilities to be multiplied directly to establish safety.","Link low-point sumps, power and maintenance isolation."],"answer":2,"explanation":"海底排水的可靠性需連結低點集水、供電與維修隔離，假想兩台泵中一台退出時，分析淨入流與警報延遲而不把原容量沿用。 其餘選項是常見誤解。","explanationEn":"Link low-point sumps, power and maintenance isolation; when one hypothetical pump is unavailable, recalculate net inflow and alarm delay rather than retaining the original capacity. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":41},{"id":"b102-v14-30","title":"停泵緩衝與有效集水容積：定量估算","titleEn":"Outage buffer and effective sump volume: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-29"],"objective":"以數值模型估算「剩餘集水容積」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Remaining sump volume” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：有效剩餘容積=320 m³；淨入流=0.19 m³/s。t=V/Q/60=28.0702 min。僅把淨入流增加10%，其他條件不變，重算為25.5183 min。邊界：停泵固定入流，不含警報延遲及水量突增；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: usable reserve=320 m³; net inflow=0.19 m³/s. t=V/Q/60=28.0702 min. Increasing only net inflow by 10% with all other inputs fixed gives 25.5183 min. Boundary: Constant inflow during outage, excluding alarm delay and inflow surges. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將水位上升曲線與當時泵啟停、閥位及出水流量同步，區分閥路阻塞和機械輸出不足。","observationEn":"How to cross-check: Synchronise level rise with pump state, valves and discharge, distinguishing blocked routing from deficient mechanical output.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：有效剩餘容積=320 m³；淨入流=0.19 m³/s。t=V/Q/60=28.0702 min。僅把淨入流增加10%，其他條件不變，重算為25.5183 min。邊界：停泵固定入流，不含警報延遲及水量突增；不是本工程實測或允收值。","textEn":"Original teaching assumptions: usable reserve=320 m³; net inflow=0.19 m³/s. t=V/Q/60=28.0702 min. Increasing only net inflow by 10% with all other inputs fixed gives 25.5183 min. Boundary: Constant inflow during outage, excluding alarm delay and inflow surges. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「停泵緩衝與有效集水容積」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Outage buffer and effective sump volume\", which statement holds?","options":["原創教學假設：有效剩餘容積=320 m³；淨入流=0.19 m³/s。","目前沒有可見漏水就能在設計中忽略外水壓。","接縫平均寬度合格就不必量測局部錯台及扭轉。"],"optionsEn":["Original teaching assumptions: usable reserve=320 m³; net inflow=0.19 m³/s. t=V/Q/60=28.0702 min.","No visible leakage means that external water pressure can be omitted from design.","An acceptable average joint width makes local offset and twist measurements unnecessary."],"answer":0,"explanation":"原創教學假設：有效剩餘容積=320 m³；淨入流=0.19 m³/s。 重算時請保留單位。","explanationEn":"Original teaching assumptions: usable reserve=320 m³; net inflow=0.19 m³/s. t=V/Q/60=28.0702 min. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":42},{"id":"b102-v14-31","title":"停泵緩衝與有效集水容積：試驗與驗證","titleEn":"Outage buffer and effective sump volume: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「剩餘集水容積」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Remaining sump volume” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將水位上升曲線與當時泵啟停、閥位及出水流量同步，區分閥路阻塞和機械輸出不足。以水位容積曲線和流量計核對停泵水位上升率，另檢查淤積、警報時間戳及備援電力切換紀錄。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Synchronise level rise with pump state, valves and discharge, distinguishing blocked routing from deficient mechanical output. Compare outage level-rise rate with the level-volume curve and flowmeter, separately checking sediment, alarm timestamps and backup-power transfer records. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「剩餘集水容積」的交付需回答：將水位上升曲線與當時泵啟停、閥位及出水流量同步，區分閥路阻塞和機械輸出不足。交接有效容積、初始水位及延遲預算，由排水與電氣責任人共同核對故障情境，定期清淤後保存量測證據。","observationEn":"Site practice: For Channel Tunnel, the remaining sump volume handover must address the following evidence: Synchronise level rise with pump state, valves and discharge, distinguishing blocked routing from deficient mechanical output. Handover usable volume, initial level and delay budgets; drainage and electrical owners jointly review failures and retain measurements after sediment removal.","failure":"注意干擾：名義備泵若共用堵塞出口，切換成功但水位仍升；應查管路而非反覆切換泵。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A spare sharing a blocked outlet can transfer successfully while water keeps rising; diagnose the route instead of repeatedly switching pumps. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-31-k1","title":"驗證方法","titleEn":"Verification method","text":"將水位上升曲線與當時泵啟停、閥位及出水流量同步，區分閥路阻塞和機械輸出不足。以水位容積曲線和流量計核對停泵水位上升率，另檢查淤積、警報時間戳及備援電力切換紀錄。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Synchronise level rise with pump state, valves and discharge, distinguishing blocked routing from deficient mechanical output. Compare outage level-rise rate with the level-volume curve and flowmeter, separately checking sediment, alarm timestamps and backup-power transfer records. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-31-k2","title":"現場實務","titleEn":"Site practice","text":"本案「剩餘集水容積」的交付需回答：將水位上升曲線與當時泵啟停、閥位及出水流量同步，區分閥路阻塞和機械輸出不足。交接有效容積、初始水位及延遲預算，由排水與電氣責任人共同核對故障情境，定期清淤後保存量測證據。","textEn":"For Channel Tunnel, the remaining sump volume handover must address the following evidence: Synchronise level rise with pump state, valves and discharge, distinguishing blocked routing from deficient mechanical output. Handover usable volume, initial level and delay budgets; drainage and electrical owners jointly review failures and retain measurements after sediment removal.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「停泵緩衝與有效集水容積」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Outage buffer and effective sump volume\"?","options":["沿用另一條隧道或另一處地層的量測結果，就可視為本工程已完成驗證。","將水位上升曲線與當時泵啟停、閥位及出水流量同步，區分閥路阻塞和機械輸出不足。","只要體積風量相同，不同海拔的空氣散熱量一定相同。"],"optionsEn":["Reusing results from another tunnel or ground formation counts as verifying this structure.","Synchronise level rise with pump state, valves and discharge, distinguishing blocked routing from deficient mechanical output.","Equal volumetric airflow provides identical cooling at every altitude."],"answer":1,"explanation":"將水位上升曲線與當時泵啟停、閥位及出水流量同步，區分閥路阻塞和機械輸出不足。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Synchronise level rise with pump state, valves and discharge, distinguishing blocked routing from deficient mechanical output. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":43},{"id":"b102-v14-32","title":"停泵緩衝與有效集水容積：失效診斷","titleEn":"Outage buffer and effective sump volume: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-31"],"objective":"從症狀倒推「剩餘集水容積」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Remaining sump volume” and propose discriminating checks, corrective actions and prevention.","instruction":"名義備泵若共用堵塞出口，切換成功但水位仍升；應查管路而非反覆切換泵。未扣除沉積的總容積會高估反應時間，若警報與抽水同失電，操作者可能在緩衝已耗盡後才得知水位上升。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A spare sharing a blocked outlet can transfer successfully while water keeps rising; diagnose the route instead of repeatedly switching pumps. Gross volume without sediment deduction overstates response time; shared loss of alarm and pumping power can hide rising water until the buffer is exhausted. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：緩衝時間取決於淨入流，不是名牌抽水能力；警報延遲、備援切換與水量突增會消耗餘裕，排水電力又可能與其他安全設備共用失效原因。","observationEn":"Link to the mechanism: Alarm delay, transfer time and inflow surges consume reserve, while shared electrical dependencies may disable drainage and other safety equipment together.","failure":"誤判風險：若相信「集水坑總容積除以平均入流就是保證可用的反應時間。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Gross sump volume divided by average inflow is a guaranteed response time.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-32-k1","title":"失效模式","titleEn":"Failure mode","text":"名義備泵若共用堵塞出口，切換成功但水位仍升；應查管路而非反覆切換泵。未扣除沉積的總容積會高估反應時間，若警報與抽水同失電，操作者可能在緩衝已耗盡後才得知水位上升。","textEn":"A spare sharing a blocked outlet can transfer successfully while water keeps rising; diagnose the route instead of repeatedly switching pumps. Gross volume without sediment deduction overstates response time; shared loss of alarm and pumping power can hide rising water until the buffer is exhausted.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「停泵緩衝與有效集水容積」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Outage buffer and effective sump volume\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","設備有兩台就可以直接把各自故障率相乘判定安全。","名義備泵若共用堵塞出口，切換成功但水位仍升；應查管路而非反覆切換泵。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Two units allow their failure probabilities to be multiplied directly to establish safety.","A spare sharing a blocked outlet can transfer successfully while water keeps rising; diagnose the route instead of repeatedly switching pumps."],"answer":2,"explanation":"名義備泵若共用堵塞出口，切換成功但水位仍升；應查管路而非反覆切換泵。 需以量測區分可能原因。","explanationEn":"A spare sharing a blocked outlet can transfer successfully while water keeps rising; diagnose the route instead of repeatedly switching pumps. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":44}],"order":7},{"id":"b102-v14-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「設備備援與共同失效」與「資產編碼與可追溯交接」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Equipment redundancy and common failure\" and \"Asset identity and traceable handover\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b102-v14-33","title":"設備備援與共同失效：機制與系統路徑","titleEn":"Equipment redundancy and common failure: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-32"],"objective":"說明「系統不可用率」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “System unavailability” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"英法跨境服務把電力、控制、冷卻與維修責任放在多個介面，設備重複不能消除共用軟體或配電故障，需以功能可用性定義頂事件。兩套設備只有在故障近似獨立且切換可靠時，並聯才顯著降低不可用率。共用配電、控制軟體、冷卻或受淹位置會把獨立假設破壞；維修停用也改變當下配置，因此可靠度模型必須明列共有資源和設備狀態，不能只數備用台數。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「系統不可用率」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Cross-border service couples power, controls, cooling and maintenance responsibilities; duplicated equipment does not eliminate shared software or distribution faults, so define top events by lost function. Parallel equipment sharply reduces unavailability only when failures are approximately independent and transfer works. Shared power, software, cooling or flood exposure breaks that assumption. Planned maintenance also changes the available configuration, so reliability models must identify shared resources and states rather than count spare units or multiply unsupported independent probabilities. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “System unavailability” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：單機不可用率=0.011 無因次。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: single-unit unavailability=0.011 dimensionless.","failure":"常見誤解：「設備有兩台就可以直接把各自故障率相乘判定安全。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Two units allow their failure probabilities to be multiplied directly to establish safety.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「系統不可用率」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “System unavailability”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-33-k1","title":"設備備援與共同失效","titleEn":"Equipment redundancy and common failure","text":"英法跨境服務把電力、控制、冷卻與維修責任放在多個介面，設備重複不能消除共用軟體或配電故障，需以功能可用性定義頂事件。兩套設備只有在故障近似獨立且切換可靠時，並聯才顯著降低不可用率。","textEn":"Cross-border service couples power, controls, cooling and maintenance responsibilities; duplicated equipment does not eliminate shared software or distribution faults, so define top events by lost function. Parallel equipment sharply reduces unavailability only when failures are approximately independent and transfer works.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：設備有兩台就可以直接把各自故障率相乘判定安全。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Two units allow their failure probabilities to be multiplied directly to establish safety. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「設備備援與共同失效」，下列哪一項敘述正確？","questionEn":"Which statement about \"Equipment redundancy and common failure\" is correct?","options":["英法跨境服務把電力、控制、冷卻與維修責任放在多個介面，設備重複不能消除共用軟體或配電故障，需以功能可用性定義頂事件。","設備有兩台就可以直接把各自故障率相乘判定安全。","全部檔案上傳完成就代表工程交接已經驗收合格。"],"optionsEn":["Cross-border service couples power, controls, cooling and maintenance responsibilities.","Two units allow their failure probabilities to be multiplied directly to establish safety.","Uploading all files means that engineering handover has been accepted."],"answer":0,"explanation":"英法跨境服務把電力、控制、冷卻與維修責任放在多個介面，設備重複不能消除共用軟體或配電故障，需以功能可用性定義頂事件。 其餘選項是常見誤解。","explanationEn":"Cross-border service couples power, controls, cooling and maintenance responsibilities; duplicated equipment does not eliminate shared software or distribution faults, so define top events by lost function. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":45},{"id":"b102-v14-34","title":"設備備援與共同失效：定量估算","titleEn":"Equipment redundancy and common failure: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-33"],"objective":"以數值模型估算「系統不可用率」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “System unavailability” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：單機不可用率=0.011 無因次。Uparallel=U²=0.000121 probability。僅把單機不可用率增加10%，其他條件不變，重算為0.00014641 probability。邊界：完全獨立並聯與完美切換，不含共同失效；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: single-unit unavailability=0.011 dimensionless. Uparallel=U²=0.000121 probability. Increasing only single-unit unavailability by 10% with all other inputs fixed gives 0.00014641 probability. Boundary: Independent parallel units with perfect transfer, excluding common failures. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：從一項失去服務的事件反向追到共用電源和控制版本，再比對維修時設備是否真的獨立。","observationEn":"How to cross-check: Trace one loss-of-service event back to common supply and control revisions and test independence during maintenance.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：單機不可用率=0.011 無因次。Uparallel=U²=0.000121 probability。僅把單機不可用率增加10%，其他條件不變，重算為0.00014641 probability。邊界：完全獨立並聯與完美切換，不含共同失效；不是本工程實測或允收值。","textEn":"Original teaching assumptions: single-unit unavailability=0.011 dimensionless. Uparallel=U²=0.000121 probability. Increasing only single-unit unavailability by 10% with all other inputs fixed gives 0.00014641 probability. Boundary: Independent parallel units with perfect transfer, excluding common failures. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「設備備援與共同失效」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Equipment redundancy and common failure\", which statement holds?","options":["混凝土強度達標就不必檢查接縫轉動與偏壓。","原創教學假設：單機不可用率=0.011 無因次。","增加工作面就可以直接把各面的理論產量相加。"],"optionsEn":["Passing concrete strength eliminates the need to check joint rotation and uneven pressure.","Original teaching assumptions: single-unit unavailability=0.011 dimensionless.","Adding headings allows their theoretical outputs to be summed directly."],"answer":1,"explanation":"原創教學假設：單機不可用率=0.011 無因次。 重算時請保留單位。","explanationEn":"Original teaching assumptions: single-unit unavailability=0.011 dimensionless. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":46},{"id":"b102-v14-35","title":"設備備援與共同失效：試驗與驗證","titleEn":"Equipment redundancy and common failure: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「系統不可用率」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “System unavailability” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"從一項失去服務的事件反向追到共用電源和控制版本，再比對維修時設備是否真的獨立。由設備清單畫出故障樹，將電源、控制及實體位置追到共同節點，並用事件及維修紀錄檢查獨立假設。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Trace one loss-of-service event back to common supply and control revisions and test independence during maintenance. Build a fault tree from the asset list, trace power, control and location to shared nodes, and test independence against incident and maintenance records. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「系統不可用率」的交付需回答：從一項失去服務的事件反向追到共用電源和控制版本，再比對維修時設備是否真的獨立。維修計畫附當日可用配置與剩餘備援，任何共同資源更動同步更新故障樹，切換試驗由設備及營運團隊共同見證。","observationEn":"Site practice: For Channel Tunnel, the system unavailability handover must address the following evidence: Trace one loss-of-service event back to common supply and control revisions and test independence during maintenance. Attach the actual configuration and remaining redundancy to maintenance plans, update fault trees after shared-resource changes, and witness transfer tests jointly.","failure":"注意干擾：把同一次共同電源故障拆成兩個獨立事件會嚴重低估並聯不可用率，且掩蓋責任介面。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Splitting one common-supply fault into independent events understates parallel unavailability and hides interface responsibility. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-35-k1","title":"驗證方法","titleEn":"Verification method","text":"從一項失去服務的事件反向追到共用電源和控制版本，再比對維修時設備是否真的獨立。由設備清單畫出故障樹，將電源、控制及實體位置追到共同節點，並用事件及維修紀錄檢查獨立假設。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Trace one loss-of-service event back to common supply and control revisions and test independence during maintenance. Build a fault tree from the asset list, trace power, control and location to shared nodes, and test independence against incident and maintenance records. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-35-k2","title":"現場實務","titleEn":"Site practice","text":"本案「系統不可用率」的交付需回答：從一項失去服務的事件反向追到共用電源和控制版本，再比對維修時設備是否真的獨立。維修計畫附當日可用配置與剩餘備援，任何共同資源更動同步更新故障樹，切換試驗由設備及營運團隊共同見證。","textEn":"For Channel Tunnel, the system unavailability handover must address the following evidence: Trace one loss-of-service event back to common supply and control revisions and test independence during maintenance. Attach the actual configuration and remaining redundancy to maintenance plans, update fault trees after shared-resource changes, and witness transfer tests jointly.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「設備備援與共同失效」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Equipment redundancy and common failure\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","動壓公式算出的數值就是長鐵路隧道完整壓力波。","從一項失去服務的事件反向追到共用電源和控制版本，再比對維修時設備是否真的獨立。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","A dynamic-pressure calculation is the complete pressure-wave prediction for a long rail tunnel.","Trace one loss-of-service event back to common supply and control revisions and test independence during maintenance."],"answer":2,"explanation":"從一項失去服務的事件反向追到共用電源和控制版本，再比對維修時設備是否真的獨立。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Trace one loss-of-service event back to common supply and control revisions and test independence during maintenance. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":47},{"id":"b102-v14-36","title":"設備備援與共同失效：失效診斷","titleEn":"Equipment redundancy and common failure: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-35"],"objective":"從症狀倒推「系統不可用率」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “System unavailability” and propose discriminating checks, corrective actions and prevention.","instruction":"把同一次共同電源故障拆成兩個獨立事件會嚴重低估並聯不可用率，且掩蓋責任介面。重複安裝卻共用單一供電可能在一次故障中全部停機，帳面可靠度很高但實際不可用時間沒有降低。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Splitting one common-supply fault into independent events understates parallel unavailability and hides interface responsibility. Duplicated equipment on one supply can fail together in a single event, leaving actual downtime unchanged despite optimistic calculated reliability. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：共用配電、控制軟體、冷卻或受淹位置會把獨立假設破壞；維修停用也改變當下配置，因此可靠度模型必須明列共有資源和設備狀態，不能只數備用台數。","observationEn":"Link to the mechanism: Planned maintenance also changes the available configuration, so reliability models must identify shared resources and states rather than count spare units or multiply unsupported independent probabilities.","failure":"誤判風險：若相信「設備有兩台就可以直接把各自故障率相乘判定安全。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Two units allow their failure probabilities to be multiplied directly to establish safety.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-36-k1","title":"失效模式","titleEn":"Failure mode","text":"把同一次共同電源故障拆成兩個獨立事件會嚴重低估並聯不可用率，且掩蓋責任介面。重複安裝卻共用單一供電可能在一次故障中全部停機，帳面可靠度很高但實際不可用時間沒有降低。","textEn":"Splitting one common-supply fault into independent events understates parallel unavailability and hides interface responsibility. Duplicated equipment on one supply can fail together in a single event, leaving actual downtime unchanged despite optimistic calculated reliability.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「設備備援與共同失效」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Equipment redundancy and common failure\" shows distress, which diagnosis is most reasonable?","options":["把同一次共同電源故障拆成兩個獨立事件會嚴重低估並聯不可用率，且掩蓋責任介面。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","全部檔案上傳完成就代表工程交接已經驗收合格。"],"optionsEn":["Splitting one common-supply fault into independent events understates parallel unavailability and hides interface responsibility.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Uploading all files means that engineering handover has been accepted."],"answer":0,"explanation":"把同一次共同電源故障拆成兩個獨立事件會嚴重低估並聯不可用率，且掩蓋責任介面。 需以量測區分可能原因。","explanationEn":"Splitting one common-supply fault into independent events understates parallel unavailability and hides interface responsibility. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":48},{"id":"b102-v14-37","title":"資產編碼與可追溯交接：機制與系統路徑","titleEn":"Asset identity and traceable handover: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-36"],"objective":"說明「資產資料完整度」如何影響英法海底隧道的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Asset-record completeness” governs forces, deformation, flow or signals in “Channel Tunnel”, and map the relevant inputs, transfer paths and boundaries.","instruction":"英法長期營運需要把更新設備與原設施共同管理，資料交接必須保留新舊版本適用里程及日期，不能讓歷史趨勢因供應商更換而中斷。地下設備的竣工資料必須讓維護人員找到正確位置、材料批次和控制版本。只有上傳圖面而沒有變更歷程，無法分辨元件替換與真正劣化；告警、儀器、線路及工單使用一致識別碼，才可能把量測趨勢連回實際受力或水力系統。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「資產資料完整度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Long-term renewal requires old and new systems to coexist in records, with chainage and dates defining each revision rather than losing historical trends when suppliers change. Handover must let maintainers find the correct location, material batch and control revision. Drawings without change history cannot distinguish replacement from deterioration. Consistent identifiers across alarms, instruments, circuits and work orders are essential for linking trends to the physical structural or hydraulic system instead of treating each record as an isolated file. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Asset-record completeness” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：設備總數=101 個；缺紀錄數=16 個。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: asset count=101 count; missing records=16 count. coverage=100(N−missing)/N=84.1584 %.","failure":"常見誤解：「全部檔案上傳完成就代表工程交接已經驗收合格。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Uploading all files means that engineering handover has been accepted.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「資產資料完整度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Asset-record completeness”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b102-v14-37-k1","title":"資產編碼與可追溯交接","titleEn":"Asset identity and traceable handover","text":"英法長期營運需要把更新設備與原設施共同管理，資料交接必須保留新舊版本適用里程及日期，不能讓歷史趨勢因供應商更換而中斷。地下設備的竣工資料必須讓維護人員找到正確位置、材料批次和控制版本。","textEn":"Long-term renewal requires old and new systems to coexist in records, with chainage and dates defining each revision rather than losing historical trends when suppliers change. Handover must let maintainers find the correct location, material batch and control revision.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：全部檔案上傳完成就代表工程交接已經驗收合格。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Uploading all files means that engineering handover has been accepted. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"關於「資產編碼與可追溯交接」，下列哪一項敘述正確？","questionEn":"Which statement about \"Asset identity and traceable handover\" is correct?","options":["全部檔案上傳完成就代表工程交接已經驗收合格。","英法長期營運需要把更新設備與原設施共同管理，資料交接必須保留新舊版本適用里程及日期，不能讓歷史趨勢因供應商更換而中斷。","目前沒有可見漏水就能在設計中忽略外水壓。"],"optionsEn":["Uploading all files means that engineering handover has been accepted.","Long-term renewal requires old and new systems to coexist in records, with chainage and dates defining each revision rather than losing historical trends when suppliers change.","No visible leakage means that external water pressure can be omitted from design."],"answer":1,"explanation":"英法長期營運需要把更新設備與原設施共同管理，資料交接必須保留新舊版本適用里程及日期，不能讓歷史趨勢因供應商更換而中斷。 其餘選項是常見誤解。","explanationEn":"Long-term renewal requires old and new systems to coexist in records, with chainage and dates defining each revision rather than losing historical trends when suppliers change. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":49},{"id":"b102-v14-38","title":"資產編碼與可追溯交接：定量估算","titleEn":"Asset identity and traceable handover: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-37"],"objective":"以數值模型估算「資產資料完整度」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Asset-record completeness” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：設備總數=101 個；缺紀錄數=16 個。coverage=100(N−missing)/N=84.1584 %。僅把缺紀錄數增加10%，其他條件不變，重算為82.5743 %。邊界：資料完整度，不等於安全或可靠度；擾動為連續敏感度，實際個數為整數；不是本工程實測或允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: asset count=101 count; missing records=16 count. coverage=100(N−missing)/N=84.1584 %. Increasing only missing records by 10% with all other inputs fixed gives 82.5743 %. Boundary: Record completeness, not safety or reliability; perturbation is continuous sensitivity while actual counts are integers. These are not project measurements or acceptance values. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：抽查更換過的感測器，從現行標籤追到舊型號校正與工單，驗證量程和零點是否可比。","observationEn":"How to cross-check: Sample a replaced sensor from its current tag back to previous calibration and work orders, checking range and zero comparability.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b102-v14-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：設備總數=101 個；缺紀錄數=16 個。coverage=100(N−missing)/N=84.1584 %。僅把缺紀錄數增加10%，其他條件不變，重算為82.5743 %。邊界：資料完整度，不等於安全或可靠度；擾動為連續敏感度，實際個數為整數；不是本工程實測或允收值。","textEn":"Original teaching assumptions: asset count=101 count; missing records=16 count. coverage=100(N−missing)/N=84.1584 %. Increasing only missing records by 10% with all other inputs fixed gives 82.5743 %. Boundary: Record completeness, not safety or reliability; perturbation is continuous sensitivity while actual counts are integers. These are not project measurements or acceptance values.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"依「資產編碼與可追溯交接」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Asset identity and traceable handover\", which statement holds?","options":["接縫平均寬度合格就不必量測局部錯台及扭轉。","只要體積風量相同，不同海拔的空氣散熱量一定相同。","原創教學假設：設備總數=101 個；缺紀錄數=16 個。"],"optionsEn":["An acceptable average joint width makes local offset and twist measurements unnecessary.","Equal volumetric airflow provides identical cooling at every altitude.","Original teaching assumptions: asset count=101 count; missing records=16 count. coverage=100(N−missing)/N=84.1584 %."],"answer":2,"explanation":"原創教學假設：設備總數=101 個；缺紀錄數=16 個。 重算時請保留單位。","explanationEn":"Original teaching assumptions: asset count=101 count; missing records=16 count. coverage=100(N−missing)/N=84.1584 %. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":50},{"id":"b102-v14-39","title":"資產編碼與可追溯交接：試驗與驗證","titleEn":"Asset identity and traceable handover: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「資產資料完整度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Asset-record completeness” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"抽查更換過的感測器，從現行標籤追到舊型號校正與工單，驗證量程和零點是否可比。抽取一條告警，從控制畫面追到設備、線路、圖面和工單，核對位置、版本及校正日期並記錄無法閉合的欄位。比對時保留校正、時間與基準版本，允收採設計核准條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Sample a replaced sensor from its current tag back to previous calibration and work orders, checking range and zero comparability. Trace a sampled alarm from screen to equipment, circuit, drawing and work order, checking location, revision and calibration dates and recording broken links. Retain calibration, timing and datum revisions, and compare against design-approved conditions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：本案「資產資料完整度」的交付需回答：抽查更換過的感測器，從現行標籤追到舊型號校正與工單，驗證量程和零點是否可比。交接以可完成的定位、查找與復原任務驗證，由維護責任人確認現場可用性；完整度只是資料指標，不代表結構安全或設備可靠。","observationEn":"Site practice: For Channel Tunnel, the asset-record completeness handover must address the following evidence: Sample a replaced sensor from its current tag back to previous calibration and work orders, checking range and zero comparability. Validate handover through achievable location, retrieval and recovery tasks witnessed by maintainers; completeness measures records, not structural safety or equipment reliability.","failure":"注意干擾：設備ID重用但未保留更換日期，會把新感測器的偏移解讀成隧道結構突然改變。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Reusing an asset ID without replacement dates can turn a new-sensor offset into a false sudden structural change. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b102-v14-39-k1","title":"驗證方法","titleEn":"Verification method","text":"抽查更換過的感測器，從現行標籤追到舊型號校正與工單，驗證量程和零點是否可比。抽取一條告警，從控制畫面追到設備、線路、圖面和工單，核對位置、版本及校正日期並記錄無法閉合的欄位。比對時保留校正、時間與基準版本，允收採設計核准條件。","textEn":"Sample a replaced sensor from its current tag back to previous calibration and work orders, checking range and zero comparability. Trace a sampled alarm from screen to equipment, circuit, drawing and work order, checking location, revision and calibration dates and recording broken links. Retain calibration, timing and datum revisions, and compare against design-approved conditions.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-39-k2","title":"現場實務","titleEn":"Site practice","text":"本案「資產資料完整度」的交付需回答：抽查更換過的感測器，從現行標籤追到舊型號校正與工單，驗證量程和零點是否可比。交接以可完成的定位、查找與復原任務驗證，由維護責任人確認現場可用性；完整度只是資料指標，不代表結構安全或設備可靠。","textEn":"For Channel Tunnel, the asset-record completeness handover must address the following evidence: Sample a replaced sensor from its current tag back to previous calibration and work orders, checking range and zero comparability. Validate handover through achievable location, retrieval and recovery tasks witnessed by maintainers; completeness measures records, not structural safety or equipment reliability.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"要驗證「資產編碼與可追溯交接」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Asset identity and traceable handover\"?","options":["抽查更換過的感測器，從現行標籤追到舊型號校正與工單，驗證量程和零點是否可比。","不確定度太難估計，報告中只寫最佳值即可。","只要出口距離短，就不需要比較可用與所需安全時間。"],"optionsEn":["Sample a replaced sensor from its current tag back to previous calibration and work orders, checking range and zero comparability.","Uncertainty is too hard to estimate, so the report may state only the best value.","Short exit distance removes the need to compare available and required safe time."],"answer":0,"explanation":"抽查更換過的感測器，從現行標籤追到舊型號校正與工單，驗證量程和零點是否可比。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Sample a replaced sensor from its current tag back to previous calibration and work orders, checking range and zero comparability. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":51},{"id":"b102-v14-40","title":"資產編碼與可追溯交接：失效診斷","titleEn":"Asset identity and traceable handover: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"],"prerequisiteIds":["b102-v14-39"],"objective":"從症狀倒推「資產資料完整度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Asset-record completeness” and propose discriminating checks, corrective actions and prevention.","instruction":"設備ID重用但未保留更換日期，會把新感測器的偏移解讀成隧道結構突然改變。設備改名卻未更新控制畫面會引導人員隔離錯誤回路，材料批次缺漏則使同批缺陷無法追蹤到其他位置。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Reusing an asset ID without replacement dates can turn a new-sensor offset into a false sudden structural change. Renaming an asset without updating the screen can isolate the wrong circuit; missing material batches prevent tracing related defects at other locations. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：只有上傳圖面而沒有變更歷程，無法分辨元件替換與真正劣化；告警、儀器、線路及工單使用一致識別碼，才可能把量測趨勢連回實際受力或水力系統。","observationEn":"Link to the mechanism: Consistent identifiers across alarms, instruments, circuits and work orders are essential for linking trends to the physical structural or hydraulic system instead of treating each record as an isolated file.","failure":"誤判風險：若相信「全部檔案上傳完成就代表工程交接已經驗收合格。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Uploading all files means that engineering handover has been accepted.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b102-v14-40-k1","title":"失效模式","titleEn":"Failure mode","text":"設備ID重用但未保留更換日期，會把新感測器的偏移解讀成隧道結構突然改變。設備改名卻未更新控制畫面會引導人員隔離錯誤回路，材料批次缺漏則使同批缺陷無法追蹤到其他位置。","textEn":"Reusing an asset ID without replacement dates can turn a new-sensor offset into a false sudden structural change. Renaming an asset without updating the screen can isolate the wrong circuit; missing material batches prevent tracing related defects at other locations.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]},{"id":"b102-v14-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-landmark-b102","b-src-underground","v14s-landmark-piarc"]}],"quiz":{"question":"在「資產編碼與可追溯交接」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Asset identity and traceable handover\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","設備ID重用但未保留更換日期，會把新感測器的偏移解讀成隧道結構突然改變。","目前沒有可見漏水就能在設計中忽略外水壓。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Reusing an asset ID without replacement dates can turn a new-sensor offset into a false sudden structural change.","No visible leakage means that external water pressure can be omitted from design."],"answer":1,"explanation":"設備ID重用但未保留更換日期，會把新感測器的偏移解讀成隧道結構突然改變。 需以量測區分可能原因。","explanationEn":"Reusing an asset ID without replacement dates can turn a new-sensor offset into a false sudden structural change. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":52}],"order":8}],"title":"英法海底隧道","titleEn":"Channel Tunnel","summary":"從白堊泥灰岩選線到三隧道營運系統，練習地質推論、支承、防水與機電整合。","summaryEn":"Study geological inference, support, water control and systems integration from chalk-marl alignment to three-bore operation.","scope":"以公開資料建立的原創教學分解；所有步驟為紙上、數位模型與證據判讀練習。自繪的示意與自設資料必須標示假設；本站未提供現地工程資料，亦不是核准施工、設備操作或水質放行程序。","scopeEn":"Original educational decomposition of public information. Every step is a paper, digital-model or evidence-interpretation exercise. Label assumptions in self-drawn diagrams and invented data; this site does not supply field engineering records or approved construction, operating or water-release procedures.","diagram":{"type":"tunnel","labels":["地層","開挖與襯砌","聯絡通道","機電","監測"],"labelsEn":["Ground","Excavation and lining","Cross-passages","Services","Monitoring"],"original":true,"notToScale":true},"stepCount":52,"estimatedMinutes":1240,"curriculumVersion":6,"enrichmentVersion":14,"learningTrack":"underground","learningSubdiscipline":"ug-landmarks","learningTags":["underground","ug-landmarks","tunnel"],"subcategory":"ug-landmarks","subcategoryTitle":"世界隧道與地下巨作","subcategoryTitleEn":"World tunnels and underground landmarks","v14Architecture":{"architectureFamily":"tunnel","architectureNodes":[["測壓水頭","Piezometric head"],["襯砌環向壓縮","Lining hoop compression"],["出渣運輸節拍","Muck-transport cycle"],["入口壓力擾動","Portal pressure disturbance"],["剩餘集水容積","Remaining sump volume"],["資產資料完整度","Asset-record completeness"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[4,5],[1,5]]},"v14Extension":{"stages":5,"steps":40,"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"原創綜合審查：先計算「環向受力與接縫柔度」，再獨立計算「列車壓力波與動壓量級」。原創教學假設：均勻外壓=0.32 MPa；半徑=3.1 m；厚度=0.35 m。σθ=pr/t=2.83429 MPa。僅把均勻外壓增加10%，其他條件不變，重算為3.11771 MPa。邊界：薄圓環膜應力，不是接縫、偏壓或矩形框架解；不是本工程實測或允收值。原創教學假設：空氣密度=1.2 kg/m³；列車速度=41 m/s。q=ρv²/2=1008.6 Pa。僅把列車速度增加10%，其他條件不變，重算為1220.41 Pa。邊界：不可壓動壓尺度，不是可壓縮列車壓力波解；不是本工程實測或允收值。兩組結果的單位與邊界不同，不能直接相加。請列出一項缺少的現場輸入，說明它會影響哪個結論，以及哪種獨立量測可以縮小不確定度。","textEn":"Original integrated review: first calculate ring force and joint flexibility, then independently calculate train pressure waves and dynamic-pressure scale. Original teaching assumptions: uniform external pressure=0.32 MPa; radius=3.1 m; thickness=0.35 m. σθ=pr/t=2.83429 MPa. Increasing only uniform external pressure by 10% with all other inputs fixed gives 3.11771 MPa. Boundary: Thin circular-ring membrane stress, not a joint, uneven-load or rectangular-frame solution. These are not project measurements or acceptance values. Original teaching assumptions: air density=1.2 kg/m³; train speed=41 m/s. q=ρv²/2=1008.6 Pa. Increasing only train speed by 10% with all other inputs fixed gives 1220.41 Pa. Boundary: Incompressible dynamic-pressure scale, not a compressible train pressure-wave solution. These are not project measurements or acceptance values. The outputs have different units and boundaries and cannot simply be added. Identify one missing field input, explain which conclusion it changes and select an independent measurement to reduce uncertainty.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"focus":"主孔服務孔介面、壓力波與長期可維護性","focusEn":"Running-bore and service-gallery interfaces, pressure waves and maintainability"}}};
